DO $$
DECLARE
  falabella_id uuid;
BEGIN
  SELECT id INTO falabella_id FROM public.companies WHERE slug = 'falabella';

  IF falabella_id IS NULL THEN
    RAISE EXCEPTION 'Company falabella not found';
  END IF;

  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'La Primera Impresión', 'La primera impresión se forma en los primeros 4 segundos de interacción. Jordan enseña que tu lenguaje corporal, tono de voz y nivel de certeza emocional influyen más que tus palabras iniciales. Debes ser "agudo como una navaja, entusiasta como el demonio y un experto en tu campo".', 'Un vendedor entra a una sala de reuniones con postura relajada, sonrisa segura y tono grave y pausado. El cliente, sin haber escuchado aún la oferta, ya percibe autoridad y confianza.', '¿Cuál es el factor más importante en los primeros segundos de una venta según Belfort?', jsonb_build_array('La presentación visual del producto', 'La energía y certeza del vendedor', 'El precio inicial ofrecido'), 'La energía y certeza del vendedor', 1 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'Los Tres Dieces', 'Para cerrar una venta, el cliente debe tener una certeza de "10 sobre 10" en tres áreas: 1) El producto/idea es excelente. 2) Confía y conecta contigo. 3) Confía en la empresa que representas. La falta de certeza en cualquiera de estas áreas es una barrera para la venta.', 'Un cliente dice: "El software parece increíble, y tú has sido muy claro, pero nunca he oído hablar de tu compañía". El vendedor sabe que debe enfocarse en aumentar la certeza sobre la empresa.', 'Un cliente ama el producto y la compañía, pero duda de ti como vendedor. ¿En cuál de los "Tres Dieces" necesitas trabajar?', jsonb_build_array('La certeza sobre el producto', 'La certeza sobre ti mismo', 'La certeza sobre la compañía'), 'La certeza sobre ti mismo', 2 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'El Umbral de Acción', 'Toda persona tiene un "umbral de acción", un nivel de certeza que debe alcanzar antes de tomar una decisión de compra. El trabajo del vendedor es usar la persuasión para llevar la certeza del cliente por encima de este umbral.', 'Un prospecto está interesado pero indeciso. El vendedor presenta un testimonio de un cliente satisfecho, aumentando la certeza y empujando al prospecto a superar su umbral de acción y comprar.', '¿Qué define el "umbral de acción" de un prospecto?', jsonb_build_array('El nivel de convencimiento que necesita para decir "sí"', 'El precio máximo que está dispuesto a pagar', 'El tiempo que tarda en tomar una decisión'), 'El nivel de convencimiento que necesita para decir "sí"', 3 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'La Recopilación de Inteligencia', 'No se debe presentar la oferta a ciegas. Es crucial hacer preguntas al inicio para entender las necesidades, creencias, valores y, sobre todo, los puntos de dolor del cliente. Esta información es vital para adaptar el discurso.', 'Vendedor: "Antes de explicarte cómo funciona, cuéntame, ¿cuál ha sido tu mayor desafío con tu sistema actual?". Esto permite descubrir un punto de dolor que podrá resolver más adelante.', '¿Cuál es el propósito principal de la recopilación de inteligencia?', jsonb_build_array('Demostrar que sabes más que el cliente', 'Adaptar tu argumento de venta a las necesidades y dolores del cliente', 'Calificar si el cliente tiene suficiente dinero'), 'Adaptar tu argumento de venta a las necesidades y dolores del cliente', 4 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'Tonalidad de Certeza Absoluta', 'El tono de voz transmite más convicción que las palabras. Usar un tono firme, claro y seguro al hablar de tu producto o idea hace que el cliente perciba tu creencia como un hecho, aumentando su propia certeza.', 'En lugar de decir "¿Crees que esto podría ayudarte?", el vendedor afirma con un tono de total seguridad: "Créeme, esto es exactamente lo que necesitas para resolver tu problema".', '¿Qué emoción principal busca transmitir la "tonalidad de certeza absoluta"?', jsonb_build_array('Duda, para que el cliente piense por sí mismo', 'Simpatía y amabilidad', 'Convicción inquebrantable'), 'Convicción inquebrantable', 5 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'El Anclaje (Emocional y de Precio)', 'El anclaje consiste en establecer un punto de referencia para el cliente. Se puede anclar un precio alto para que el precio real parezca una gran oferta, o anclar una emoción positiva a tu producto.', '"Normalmente, un sistema con estas características cuesta sobre los $10,000. Sin embargo, hoy te lo puedo ofrecer por solo $4,500". El primer precio ancla al cliente, haciendo que el segundo parezca mucho más razonable.', '¿Cuál es el objetivo de anclar un precio alto al inicio de la negociación?', jsonb_build_array('Hacer que el precio final parezca más atractivo en comparación', 'Asustar al cliente para que se vaya', 'Demostrar el valor real del producto'), 'Hacer que el precio final parezca más atractivo en comparación', 6 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'El Guion de la Línea Recta', 'Toda la venta debe seguir un guion estructurado que te lleve en línea recta desde la apertura hasta el cierre. El guion no es para leerlo, sino para interiorizar la estructura y los puntos clave, asegurando que no te desvíes del objetivo.', 'Un vendedor novato se pierde en conversaciones irrelevantes. Un vendedor de la Línea Recta, después de crear rapport, retoma el control diciendo: "Suena fascinante, y la razón por la que te llamo es que puedo ayudarte a...".', '¿Por qué es fundamental tener un guion según Belfort?', jsonb_build_array('Para no tener que pensar durante la llamada', 'Para mantener el control de la conversación y dirigirla hacia el cierre', 'Para que todos los vendedores digan exactamente las mismas palabras'), 'Para mantener el control de la conversación y dirigirla hacia el cierre', 7 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'El Bucle o Loop', 'Cuando un cliente expresa una objeción o duda, no se discute. Se utiliza un "bucle": se responde brevemente a la objeción y se aprovecha para volver a la línea recta y seguir construyendo certeza sobre uno de los "Tres Dieces".', 'Cliente: "Es muy caro". Vendedor: "Entiendo, el precio es un punto importante y te mostraré por qué tiene el mejor valor del mercado. Pero déjame preguntarte, ¿te gusta la idea del producto? ¿Ves cómo resolvería tu problema?".', '¿Cuándo se utiliza un "bucle" en el sistema de la Línea Recta?', jsonb_build_array('Al principio de la llamada para presentarse', 'Justo antes de pedir el cierre final', 'Cuando el cliente plantea una objeción, para re-enfocar la conversación'), 'Cuando el cliente plantea una objeción, para re-enfocar la conversación', 8 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'Tonalidad de Escasez y Urgencia', 'Para motivar la decisión, se utiliza un tono que sugiere que la oportunidad es limitada. Frases como "Solo nos quedan dos unidades a este precio" deben decirse con un tono bajo, rápido y casi como un susurro, como si se compartiera un secreto importante.', 'Vendedor (bajando la voz): "Mira, no debería decirte esto, pero el precio sube la próxima semana, y quiero que aproveches la oferta actual".', '¿Cómo debe ser el tono al comunicar escasez?', jsonb_build_array('Confidencial y urgente para impulsar a la acción', 'Fuerte y dominante para demostrar autoridad', 'Lento y pausado para que el cliente no se sienta presionado'), 'Confidencial y urgente para impulsar a la acción', 9 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'Umbral del Dolor', 'El dolor es un motivador más fuerte que el placer. El vendedor debe identificar el punto de dolor del cliente (su problema actual) y amplificarlo sutilmente para que sienta la necesidad urgente de una solución (tu producto).', '"Cada mes que sigues sin nuestro sistema, ¿cuánto dinero estás perdiendo exactamente por la ineficiencia? Si son $1,000 al mes, en un año son $12,000 tirados a la basura".', '¿Por qué es importante identificar y agudizar el "umbral del dolor"?', jsonb_build_array('Para hacer sentir mal al cliente', 'Para crear una necesidad inmediata de la solución que ofreces', 'Para saber si el cliente puede permitirse el producto'), 'Para crear una necesidad inmediata de la solución que ofreces', 10 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'Empatía Lógica vs. Emocional', 'La gente compra por emoción y justifica con lógica. Debes conectar primero con la emoción del cliente (empatía emocional) y luego darle los argumentos lógicos para que pueda justificar la compra ante sí mismo y ante otros.', 'Primero, el vendedor habla de la tranquilidad y seguridad que el producto le dará al cliente (emoción). Luego, le entrega una ficha técnica con datos, ROI y estadísticas (lógica).', 'Según Belfort, ¿en qué orden se deben apelar la emoción y la lógica?', jsonb_build_array('Primero la emoción para crear el deseo, luego la lógica para justificarlo', 'Primero la lógica, luego la emoción', 'Solo la emoción, la lógica no importa'), 'Primero la emoción para crear el deseo, luego la lógica para justificarlo', 11 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'El Poder de "Solo para que sepas"', 'Esta es una frase de transición poderosa para introducir los beneficios de tu producto de una manera no confrontacional. Reduce la presión y suena como si estuvieras ofreciendo información útil en lugar de vender agresivamente.', '"Solo para que sepas, una de las grandes ventajas de este sistema es que se integra perfectamente con el software que ya utilizas, ahorrándote semanas de trabajo".', '¿Qué efecto tiene la frase "Solo para que sepas"?', jsonb_build_array('Aumenta la presión de venta', 'Suaviza la presentación de un beneficio, haciéndola parecer informativa', 'Confunde al cliente'), 'Suaviza la presentación de un beneficio, haciéndola parecer informativa', 12 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'El Lenguaje Corporal', 'Tu postura, gestos y contacto visual son cruciales para generar confianza. Un lenguaje corporal abierto y seguro (espalda recta, gestos amplios, contacto visual firme) refuerza tu mensaje y transmite certeza.', 'Durante una presentación, un vendedor se inclina ligeramente hacia adelante, asiente mientras el cliente habla y utiliza las manos para enfatizar puntos clave, proyectando interés y confianza.', '¿Qué tipo de lenguaje corporal debilita tu posición de venta?', jsonb_build_array('Mantener contacto visual', 'Asentir para demostrar que estás escuchando', 'Cruzar los brazos y evitar la mirada del cliente'), 'Cruzar los brazos y evitar la mirada del cliente', 13 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'Tonalidad de "Hombre Razonable"', 'Cuando encuentras resistencia, en lugar de presionar, adoptas un tono calmado y razonable. "Entiendo tu punto de vista, ¿pero no estarías de acuerdo en que si pudieras resolver X, valdría la pena?". Esto desarma al cliente y lo invita a la lógica.', 'Cliente: "No quiero comprometerme ahora". Vendedor (con tono calmado): "Comprendo perfectamente. Dejando el dinero a un lado por un momento, ¿tiene sentido la idea para ti? ¿Crees que te beneficiaría?".', '¿En qué situación es más efectivo el tono de "hombre razonable"?', jsonb_build_array('Al inicio de la venta para mostrar energía', 'Para manejar una objeción y reducir la confrontación', 'Al comunicar escasez y urgencia'), 'Para manejar una objeción y reducir la confrontación', 14 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'Frases Pre-diseñadas para Refutar', 'Para cada objeción común ("es muy caro", "tengo que hablarlo con mi socio", "no tengo tiempo"), debes tener una respuesta pre-diseñada y ensayada. Esto te permite responder con confianza y sin dudar, manteniendo el control de la conversación.', 'Ante "Tengo que pensarlo", el vendedor responde inmediatamente: "Entiendo, las buenas decisiones requieren reflexión. Pero dime, ¿es una cuestión de dinero o te genera dudas la idea en sí?".', '¿Cuál es la ventaja de tener refutaciones pre-diseñadas?', jsonb_build_array('Responder a las objeciones de forma rápida, segura y efectiva', 'No tener que escuchar realmente la objeción del cliente', 'Hacer que la conversación sea más larga'), 'Responder a las objeciones de forma rápida, segura y efectiva', 15 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'El Cierre Suave', 'En lugar de una pregunta de cierre agresiva como "¿Entonces, lo compras?", se utilizan cierres más suaves que asumen la venta y se enfocan en los detalles logísticos.', '"Perfecto. Entonces, ¿a qué dirección te gustaría que te enviáramos el paquete inicial?" o "¿Qué nombre debería poner en el contrato?".', '¿Qué caracteriza a un "cierre suave"?', jsonb_build_array('Pregunta directamente si el cliente quiere comprar', 'Ofrece un gran descuento en el último momento', 'Asume la venta y pregunta por detalles secundarios o logísticos'), 'Asume la venta y pregunta por detalles secundarios o logísticos', 16 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'Gestión del Estado Emocional', 'No puedes persuadir a nadie si no estás en un estado emocional de certeza, claridad y confianza. Belfort enseña técnicas (como el anclaje de PNL o el uso de aromas y música) para cambiar tu estado instantáneamente antes de una interacción importante.', 'Antes de una llamada de ventas crucial, un vendedor escucha una canción que le llena de energía, se pone de pie y adopta una postura de poder para entrar en un estado de máxima confianza.', '¿Por qué es fundamental la gestión del estado para un vendedor?', jsonb_build_array('Para impresionar a sus compañeros de trabajo', 'Porque el estado emocional del vendedor se transfiere directamente al cliente', 'Para cumplir con las normas de la empresa'), 'Porque el estado emocional del vendedor se transfiere directamente al cliente', 17 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'La Importancia del "Porqué"', 'Debes tener claro tu "porqué": la razón profunda por la que haces lo que haces. Conectar con tu propósito te da la motivación y la resiliencia para superar los rechazos y mantenerte enfocado en tus metas.', 'Un vendedor no solo busca ganar una comisión, sino que su "porqué" es darle una vida mejor a su familia. Esta motivación más profunda le ayuda a perseverar en los días difíciles.', '¿Cuál es la función del "porqué" en el sistema de Belfort?', jsonb_build_array('Es una técnica para usar con los clientes', 'Es la fuente de motivación interna y resiliencia del vendedor', 'Es una forma de justificar el precio del producto'), 'Es la fuente de motivación interna y resiliencia del vendedor', 18 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'Romper Patrones de Comportamiento', 'Los clientes están acostumbrados a un tipo de discurso de venta. Para captar su atención, debes romper ese patrón. Esto se puede hacer con una pregunta inesperada, un tono de voz inusual o una declaración audaz en los primeros segundos.', 'En lugar de "Hola, soy Juan de la empresa X", empezar con: "Hola, sé que no me esperabas, pero necesito 60 segundos de tu tiempo para mostrarte algo que puede cambiar tu forma de hacer negocios. ¿Los tienes?".', '¿Cuál es el objetivo de romper el patrón de comportamiento de un cliente?', jsonb_build_array('Molestar al cliente', 'Captar su atención inmediata y diferenciarte del resto', 'Hacer la conversación más predecible'), 'Captar su atención inmediata y diferenciarte del resto', 19 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'El Poder de la Palabra "Porque"', 'Dar una razón, cualquier razón, aumenta significativamente las posibilidades de que alguien acceda a tu petición. La palabra "porque" activa una respuesta automática de aceptación en el cerebro.', 'En lugar de "¿Puedo mostrarte algo?", decir: "¿Puedo mostrarte algo, porque creo que te va a resultar extremadamente útil para reducir costes?".', '¿Qué hace que la palabra "porque" sea tan persuasiva?', jsonb_build_array('Es una palabra que denota autoridad', 'Suena formal y profesional', 'Proporciona una justificación a una petición, lo que la hace más aceptable'), 'Proporciona una justificación a una petición, lo que la hace más aceptable', 20 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'Tonalidad de Misterio e Intriga', 'Para mantener al prospecto enganchado, utiliza un tono que genere intriga y curiosidad. Habla como si estuvieras a punto de revelar un secreto importante, haciendo que el cliente quiera saber más.', 'Vendedor (con voz intrigante): "Lo que la mayoría de la gente en tu industria no sabe... es que hay una forma mucho más simple de lograr esto. Déjame explicarte...".', '¿Qué se busca conseguir con un tono de misterio?', jsonb_build_array('Generar curiosidad y hacer que el prospecto quiera escuchar más', 'Confundir al prospecto', 'Demostrar que eres un experto en el tema'), 'Generar curiosidad y hacer que el prospecto quiera escuchar más', 21 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'Usar el Dolor Futuro', 'Además de agudizar el dolor presente, se debe proyectar el dolor futuro. Consiste en hacer que el cliente visualice las consecuencias negativas de no actuar ahora y cómo su problema empeorará con el tiempo.', '"Si ahora mismo la ineficiencia te cuesta $500 al mes, en seis meses habrás perdido $3,000. ¿Qué podrías haber hecho con ese dinero? Y si la competencia adopta esta tecnología antes que tú, ¿dónde te dejará eso?".', '¿Cuál es la finalidad de proyectar el dolor futuro?', jsonb_build_array('Asustar al cliente sin un propósito claro', 'Crear un sentido de urgencia demostrando las consecuencias de la inacción', 'Hacer que el cliente se sienta mal por sus decisiones pasadas'), 'Crear un sentido de urgencia demostrando las consecuencias de la inacción', 22 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'El Placer Futuro', 'Es la contraparte del dolor futuro. Debes ayudar al cliente a visualizar vívidamente los beneficios y el estado positivo que alcanzará una vez que compre tu producto. Es pintar un cuadro de su éxito gracias a tu solución.', '"Imagina dentro de seis meses, con todo este tiempo extra que has ahorrado, pudiendo salir de la oficina a las 5 p.m. todos los días para estar con tu familia. ¿Cómo te sentirías?".', '¿Qué técnica de persuasión se basa en ayudar al cliente a visualizar los beneficios?', jsonb_build_array('El anclaje de precios', 'La proyección del placer futuro', 'La recopilación de inteligencia'), 'La proyección del placer futuro', 23 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'Transiciones Energéticas', 'Una transición energética es una frase corta que se usa para mantener el flujo de la conversación y redirigirla suavemente hacia la línea recta. Ayuda a conectar ideas de forma natural.', 'Después de que el cliente habla de un problema, el vendedor dice: "Y por eso mismo te llamo... nuestro sistema está diseñado específicamente para solucionar eso". Otras frases son: "Y lo mejor de todo es...", "De hecho...".', '¿Cuál es el propósito de una "transición energética"?', jsonb_build_array('Terminar la conversación', 'Conectar partes de la conversación de forma fluida y mantener el control', 'Cambiar de tema de forma abrupta'), 'Conectar partes de la conversación de forma fluida y mantener el control', 24 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'Calificar al Comprador', 'No todos los prospectos son compradores potenciales. Es crucial calificar rápidamente si el cliente tiene una necesidad real, el poder de decisión y la capacidad financiera para comprar. No se debe perder tiempo con quien no puede o no va a comprar.', 'Vendedor: "Este tipo de solución suele ser una inversión importante. ¿Es usted la persona encargada de aprobar estos presupuestos o hay alguien más involucrado en la decisión?".', '¿Por qué es importante calificar al comprador al inicio del proceso?', jsonb_build_array('Para asegurarse de no perder tiempo con personas que no pueden comprar', 'Para hacer sentir al cliente que está siendo interrogado', 'Para venderle el producto más caro posible'), 'Para asegurarse de no perder tiempo con personas que no pueden comprar', 25 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'El Poder del Silencio', 'Después de hacer una pregunta de cierre o una declaración poderosa, quédate en silencio. La primera persona que habla, pierde. El silencio crea una presión sutil que impulsa al cliente a responder y tomar una decisión.', 'Vendedor: "Entonces, ¿empezamos con el paquete estándar o el premium?". Inmediatamente después, el vendedor se calla y espera la respuesta del cliente, sin añadir nada más.', '¿Cuándo es especialmente poderoso usar el silencio?', jsonb_build_array('Al principio de la llamada para crear misterio', 'Inmediatamente después de hacer una pregunta de cierre', 'Mientras el cliente está hablando para interrumpirlo'), 'Inmediatamente después de hacer una pregunta de cierre', 26 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'La Certeza se Transfiere', 'La certeza es un estado emocional que se puede transferir de una persona a otra. Si tú crees al 100% en tu producto, en ti mismo y en tu empresa, esa convicción se transmitirá al cliente y aumentará su propio nivel de certeza.', 'Dos vendedores venden el mismo producto. El primero duda y usa un lenguaje débil. El segundo habla con una pasión y convicción inquebrantables. El segundo vendedor cerrará muchas más ventas.', '¿Cuál es la premisa fundamental detrás del concepto de la "transferencia de certeza"?', jsonb_build_array('Los clientes solo compran productos que ya conocen', 'Es necesario mentir para generar certeza', 'La convicción y la emoción del vendedor influyen directamente en la del cliente'), 'La convicción y la emoción del vendedor influyen directamente en la del cliente', 27 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'Refutación "Siente, Sentía, Encontraron"', 'Es una fórmula clásica para manejar objeciones validando los sentimientos del cliente. "Entiendo cómo te sientes. Otros clientes se sentían de la misma manera al principio. Pero lo que encontraron fue que [beneficio]".', 'Cliente: "Es demasiado caro". Vendedor: "Entiendo cómo te sientes con el precio. Honestamente, muchos de mis mejores clientes se sentían exactamente igual. Pero lo que encontraron fue que el ahorro en tiempo y errores les devolvía la inversión en menos de 6 meses".', '¿Qué logra la fórmula "Siente, Sentía, Encontraron"?', jsonb_build_array('Ignorar la objeción del cliente', 'Validar la emoción del cliente mientras se le guía hacia una nueva perspectiva', 'Probar que el cliente está equivocado'), 'Validar la emoción del cliente mientras se le guía hacia una nueva perspectiva', 28 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'El Cierre de la Segunda Alternativa', 'En lugar de preguntar "Sí o No", se ofrecen dos opciones donde ambas implican que el cliente va a comprar. Esto facilita la decisión y mueve la conversación hacia adelante.', '"Entonces, ¿prefieres la instalación el martes por la mañana o el viernes por la tarde te viene mejor?". En ambos casos, se asume que la instalación se hará.', 'El cierre de la segunda alternativa está diseñado para...', jsonb_build_array('Darle al cliente la opción de decir "no" fácilmente', 'Hacer la decisión más fácil para el cliente, asumiendo la venta', 'Ofrecer un descuento en una de las dos opciones'), 'Hacer la decisión más fácil para el cliente, asumiendo la venta', 29 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'Vender la Visión', 'Los grandes líderes y vendedores no solo venden un producto, venden una visión. Inspiran a la gente con una idea de un futuro mejor y les muestran cómo pueden ser parte de esa visión.', 'Steve Jobs no vendía un reproductor de música, vendía "mil canciones en tu bolsillo". No vendía un ordenador, vendía una herramienta para cambiar el mundo.', '¿Qué significa "vender la visión"?', jsonb_build_array('Vender las características técnicas del producto', 'Vender una idea inspiradora de un futuro mejor en la que tu producto juega un papel clave', 'Mostrarle al cliente una imagen del producto'), 'Vender una idea inspiradora de un futuro mejor en la que tu producto juega un papel clave', 30 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'La Ética en la Línea Recta', 'Belfort insiste en que el sistema de la Línea Recta debe usarse éticamente. Esto significa no presionar a alguien para que compre algo que no necesita o no puede permitirse. El objetivo es ayudar a personas que se beneficiarán de tu producto.', 'Un vendedor se da cuenta de que su producto realmente no es la solución adecuada para el problema del cliente. En lugar de forzar la venta, le recomienda honestamente otra solución, construyendo confianza a largo plazo.', '¿Cuál es el pilar ético del sistema de la Línea Recta?', jsonb_build_array('Vender a toda costa, sin importar las consecuencias', 'Persuadir a la gente para que compre solo si se beneficiarán genuinamente del producto', 'Usar la persuasión solo con personas que no tienen conocimientos'), 'Persuadir a la gente para que compre solo si se beneficiarán genuinamente del producto', 31 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'Escribir para Ser Hablado', 'Al crear un guion, no debe sonar como un texto escrito, sino como un diálogo natural. Usa lenguaje conversacional, frases cortas y pausas. El guion debe ser una guía, no una cárcel.', 'Guion escrito: "Procederé a elucidar las múltiples ventajas sinérgicas de nuestra plataforma". Guion hablado: "Y déjame contarte lo mejor... esto funciona de maravilla con lo que ya tienes".', '¿Cómo debe ser el lenguaje de un guion de ventas efectivo?', jsonb_build_array('Formal, técnico y complejo para demostrar experiencia', 'Conversacional, natural y fácil de decir', 'Poético y literario para captar la atención'), 'Conversacional, natural y fácil de decir', 32 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'El Poder de la Coletilla "..., ¿verdad?"', 'Añadir una pequeña pregunta de confirmación al final de una frase ("..., ¿verdad?", "..., ¿no es así?", "..., ¿tiene sentido?") fomenta pequeños acuerdos a lo largo de la conversación, manteniendo al cliente comprometido y asintiendo.', '"Ahorrar un 20% en costos operativos sería un gran impulso para el negocio, ¿verdad?".', '¿Qué se busca al usar coletillas como "..., ¿verdad?"?', jsonb_build_array('Mostrar duda sobre lo que se acaba de decir', 'Obtener pequeños "síes" y mantener al cliente involucrado en la conversación', 'Hacer la frase más larga y completa'), 'Obtener pequeños "síes" y mantener al cliente involucrado en la conversación', 33 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'El Momentum en la Venta', 'La venta es una transferencia de emoción y tiene un momentum. Una vez que empiezas a obtener pequeños "síes" y a construir certeza, es crucial mantener esa energía y no permitir que la conversación se enfríe o se desvíe.', 'Después de que el cliente acepta un punto importante, el vendedor inmediatamente pasa al siguiente, diciendo: "¡Exacto! Y además de eso, también resuelve...".', '¿Por qué es importante mantener el "momentum" en la venta?', jsonb_build_array('Para hablar lo más rápido posible', 'Para construir sobre la emoción positiva y la certeza acumulada, sin dejar que se disipe', 'Para asegurarse de cubrir todos los puntos del guion'), 'Para construir sobre la emoción positiva y la certeza acumulada, sin dejar que se disipe', 34 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'Empaquetar la Oferta', 'En lugar de solo vender un producto, se debe empaquetar como una oferta irresistible. Esto incluye añadir bonus, garantías, un plan de pago o cualquier elemento que aumente el valor percibido y reduzca el riesgo para el cliente.', '"Si decides unirte hoy, no solo obtendrás el software, sino que también te incluiré mi curso de formación avanzada valorado en $500 y 3 meses de soporte premium totalmente gratis".', '¿Cuál es el propósito de "empaquetar la oferta"?', jsonb_build_array('Aumentar el precio final', 'Incrementar el valor percibido y hacer que la decisión de compra sea más fácil', 'Deshacerse de productos que no se venden'), 'Incrementar el valor percibido y hacer que la decisión de compra sea más fácil', 35 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'Aislar la Objeción', 'Cuando un cliente da una objeción, antes de refutarla, aíslala para asegurarte de que es la única barrera real. Se hace preguntando: "Además de [la objeción], ¿hay algo más que te impida seguir adelante?".', 'Cliente: "Es muy caro". Vendedor: "Entiendo. Aparte del precio, ¿hay alguna otra razón por la que no harías esto? Si el dinero no fuera un problema, ¿sería esto algo que querrías?".', '¿Para qué sirve "aislar la objeción"?', jsonb_build_array('Para ignorar lo que el cliente dijo', 'Para confirmar si esa es la única y verdadera barrera para la venta', 'Para encontrar más objeciones y problemas'), 'Para confirmar si esa es la única y verdadera barrera para la venta', 36 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'Vender a los Tres Cerebros', 'Se debe apelar a los tres niveles del cerebro: el cerebro reptiliano (instinto, urgencia, dolor/placer), el límbico (emociones, relaciones) y el neocórtex (lógica, datos, justificación). Una venta completa los aborda todos.', 'Apelar al reptiliano (urgencia: "la oferta termina hoy"), al límbico (emoción: "imagina la tranquilidad que sentirás") y al neocórtex (lógica: "el ROI es del 250% en el primer año").', '¿A qué se refiere "vender a los tres cerebros"?', jsonb_build_array('A tener tres vendedores en una reunión', 'A adaptar el mensaje para apelar al instinto, la emoción y la lógica del cliente', 'A repetir el mismo mensaje tres veces'), 'A adaptar el mensaje para apelar al instinto, la emoción y la lógica del cliente', 37 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'La Ley de la Congruencia', 'Tus palabras, tu tono de voz, tu lenguaje corporal y tus acciones deben estar alineados. Si dices que tienes certeza pero tu voz tiembla, el cliente percibirá la incongruencia y desconfiará.', 'Un vendedor dice "Este es el mejor producto del mercado" mientras mira al suelo y se encoge de hombros. El mensaje no es creíble. El vendedor exitoso lo dice con convicción, mirando al cliente a los ojos.', '¿Qué es la incongruencia en una venta?', jsonb_build_array('Cuando el precio no coincide con el valor', 'Cuando el lenguaje verbal y no verbal del vendedor se contradicen', 'Cuando el cliente y el vendedor no están de acuerdo'), 'Cuando el lenguaje verbal y no verbal del vendedor se contradicen', 38 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'El Cierre es una Conclusión Lógica', 'El cierre no debe ser un evento sorpresivo o de alta presión. Si has seguido la Línea Recta correctamente, has construido los Tres Dieces y has manejado las objeciones, el cierre es simplemente la conclusión natural y lógica de la conversación.', 'Vendedor: "Bien, hemos visto que el producto es perfecto para ti, que somos la empresa adecuada y que te he resuelto todas las dudas. El siguiente paso lógico es empezar. ¿Usamos tu nombre completo para el acuerdo?".', '¿Cómo debe sentirse el cierre en el sistema de la Línea Recta?', jsonb_build_array('Como un momento tenso y conflictivo', 'Como el siguiente paso obvio y natural en la conversación', 'Como una sorpresa total para el cliente'), 'Como el siguiente paso obvio y natural en la conversación', 39 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'el-camino-del-lobo', 'El Camino del Lobo', 'El Poder de la Repetición', 'La persuasión requiere repetición. Los puntos clave de tu argumento, especialmente aquellos que construyen certeza, deben repetirse varias veces a lo largo de la conversación, a menudo usando diferentes palabras o desde diferentes ángulos.', 'Un vendedor puede mencionar un beneficio clave al principio, luego contarlo a través de la historia de un cliente en el medio, y finalmente resumirlo antes del cierre.', '¿Por qué es importante la repetición en un argumento de venta?', jsonb_build_array('Porque los clientes suelen olvidar lo que se les dice', 'Porque refuerza los mensajes clave y aumenta la probabilidad de que sean aceptados', 'Porque ayuda a que el guion sea más largo'), 'Porque refuerza los mensajes clave y aumenta la probabilidad de que sean aceptados', 40 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'Sé un Espejo (Mirroring)', 'La técnica del espejo consiste en repetir las últimas 1-3 palabras clave del interlocutor, en forma de pregunta o con una inflexión ascendente. Esto crea rapport e incita a la otra persona a elaborar su punto de vista sin sentirse presionada.', 'Cliente: “No estoy seguro de que esto sea prioritario ahora”. Vendedor: “¿No es prioritario ahora?”. Cliente: “Claro, es que tengo otro proyecto en paralelo, pero este me interesa para el próximo trimestre”.', '¿Cuál es el principal objetivo del uso del espejo?', jsonb_build_array('Confirmar que se escuchó bien lo que dijo', 'Hacer que el cliente se sienta vigilado', 'Hacer que el cliente hable más y se abra'), 'Hacer que el cliente hable más y se abra', 1 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'Etiquetado (Labeling)', 'El etiquetado consiste en verbalizar la emoción o la dinámica que percibes en la otra persona. Se usan frases como "Parece que...", "Suena como si...", "Da la impresión de que...". Esto valida los sentimientos del otro y lo desarma.', 'Un cliente suena frustrado por teléfono. El negociador dice: "Parece que ha sido un día muy frustrante para usted". El cliente se siente comprendido y baja la guardia.', '¿Qué frase es un ejemplo de "etiquetado"?', jsonb_build_array('"Suena como si estuvieras preocupado por el plazo de entrega"', '"¿Por qué estás enojado?"', '"Deberías calmarte"'), '"Suena como si estuvieras preocupado por el plazo de entrega"', 2 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'El Poder de un "No"', 'Contrario a la venta tradicional, un "No" al principio de una negociación es bueno. Permite a la otra persona sentirse segura y en control. Un "No" no es el final de la conversación, sino el principio de la negociación real.', 'Negociador: "¿Sería una mala idea continuar esta conversación la próxima semana?". El cliente puede decir "No, no sería mala idea", permitiendo que la conversación continúe sin sentirse comprometido.', 'Según Chris Voss, ¿qué significa realmente un "No"?', jsonb_build_array('Una oportunidad para que la otra parte se sienta segura y aclare su posición', 'El fin absoluto de la negociación', 'Una señal de que el cliente es grosero'), 'Una oportunidad para que la otra parte se sienta segura y aclare su posición', 3 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'Conseguir un "Así es" (That''s Right)', 'El momento mágico en una negociación es cuando la otra parte dice "Así es". Esto indica que se sienten totalmente comprendidos por ti. Se logra resumiendo de manera precisa sus emociones y su posición. Es mucho más poderoso que un simple "sí".', '"Suena como si sintieras que nadie valora el esfuerzo extra que has puesto en este proyecto y te preocupa que el nuevo plan ignore todo ese trabajo". Cliente: "Así es".', '¿Qué indica que has tenido éxito al resumir la posición de tu contraparte?', jsonb_build_array('Que te digan "Así es"', 'Que te digan "Tienes razón"', 'Que se queden en silencio'), 'Que te digan "Así es"', 4 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'Preguntas Calibradas', 'Son preguntas abiertas, generalmente comenzando con "Qué" o "Cómo", que obligan a la otra parte a pensar y revelar información. Evitan respuestas de "sí" o "no" y le dan al otro la ilusión de control.', 'En lugar de "¿Puedes hacer esto por 500?", preguntar: "¿Cómo podemos llegar a un precio que sea justo para ambos?". En lugar de "¿Por qué hiciste eso?", preguntar: "¿Qué buscabas lograr con eso?".', '¿Cuál de las siguientes es una pregunta calibrada?', jsonb_build_array('"¿Aceptas la oferta?"', '"¿Qué aspecto de esto es el más importante para ti?"', '"¿Es esta tu decisión final?"'), '"¿Qué aspecto de esto es el más importante para ti?"', 5 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'La Auditoría de Acusaciones', 'Consiste en anticiparse y verbalizar todas las posibles acusaciones negativas que la otra parte podría tener sobre ti o tu propuesta, incluso antes de que las digan. Esto neutraliza los miedos y las dinámicas negativas.', '"Probablemente pienses que soy otro vendedor agresivo que solo quiere tu dinero y que te estoy presionando para que tomes una decisión rápida".', '¿Cuál es el propósito de una "auditoría de acusaciones"?', jsonb_build_array('Desarmar las emociones negativas del interlocutor antes de que se conviertan en un problema', 'Acusar a la otra parte de tener malos pensamientos', 'Pedir disculpas por tus errores'), 'Desarmar las emociones negativas del interlocutor antes de que se conviertan en un problema', 6 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'Evita preguntar "¿Por qué?"', 'La pregunta "¿Por qué?" suele poner a la gente a la defensiva, como si tuvieran que justificar sus acciones. Es mejor reformularla usando "Qué". En lugar de "¿Por qué hiciste eso?", pregunta "¿Qué te hizo hacer eso?".', 'En lugar de "¿Por qué elegiste a ese proveedor?", es más efectivo preguntar: "¿Qué factores te llevaron a elegir a ese proveedor?".', '¿Por qué se debe tener cuidado al usar la pregunta "¿Por qué?"?', jsonb_build_array('Porque puede sonar acusatoria y poner a la gente a la defensiva', 'Porque casi nunca se obtiene una respuesta honesta', 'Porque es una pregunta muy larga'), 'Porque puede sonar acusatoria y poner a la gente a la defensiva', 7 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'Crear la Ilusión de Control', 'La gente necesita sentir que tiene el control. Usando preguntas calibradas y espejos, puedes guiar la conversación mientras haces que la otra persona sienta que está tomando las decisiones y encontrando las soluciones.', 'En lugar de decir "Tienes que reducir el precio un 15%", preguntar: "¿Cómo se supone que voy a pagar ese precio?". Esto pone la pelota en su tejado y le hace buscar una solución.', '¿Cómo se crea la "ilusión de control" en la contraparte?', jsonb_build_array('Usando preguntas abiertas que les hagan sentir que están liderando la conversación', 'Imponiendo tu solución de forma directa', 'Aceptando todas sus demandas sin negociar'), 'Usando preguntas abiertas que les hagan sentir que están liderando la conversación', 8 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'Anclaje Emocional', 'Antes de hablar de cifras, se puede anclar la negociación en un plano emocional. Al realizar una auditoría de acusaciones o mostrar empatía, puedes predisponer a la otra parte a ser más colaborativa antes de que el dinero entre en juego.', '"Sé que la última negociación fue muy tensa y probablemente esperas que esta sea igual de difícil...". Esto ancla la conversación en una emoción (tensión) para luego poder desactivarla.', '¿Qué es el "anclaje emocional"?', jsonb_build_array('Ignorar las emociones y centrarse solo en los hechos', 'Utilizar las emociones para preparar el terreno antes de una negociación difícil', 'Fijar el primer precio en la mesa'), 'Utilizar las emociones para preparar el terreno antes de una negociación difícil', 9 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'El Modelo Ackerman de Regateo', 'Es un sistema para negociar precios. Consiste en: 1) Fijar un precio objetivo. 2) Empezar con una oferta inicial del 65%. 3) Realizar 3 aumentos decrecientes (al 85%, 95% y 100%). 4) Usar cifras precisas y no redondeadas. 5) Terminar con un elemento no monetario para sellar el trato.', 'Objetivo: $100. Oferta 1: $65. Oferta 2: $85. Oferta 3: $95. Oferta Final: "$98.73, y es todo lo que tengo". Luego añadir: "...y te lo pago ahora mismo".', 'En el modelo Ackerman, ¿cómo deben ser las contraofertas?', jsonb_build_array('Siempre del mismo tamaño', 'Siempre en números redondos', 'Cada vez más pequeñas para señalar que te acercas a tu límite'), 'Cada vez más pequeñas para señalar que te acercas a tu límite', 10 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'Identificar el Estilo del Negociador', 'Voss clasifica a los negociadores en tres tipos: Analista (metódico, necesita datos), Acomodador (valora la relación, le cuesta decir no) y Asertivo (directo, centrado en ganar). Adaptar tu estrategia a su estilo es clave.', 'Si negocias con un Analista, prepárate con datos, estadísticas y tiempo para que procese la información. Con un Asertivo, usa espejos y etiquetas para que no te avasalle.', '¿Cómo deberías negociar con un "Acomodador"?', jsonb_build_array('Siendo muy agresivo, porque cederá fácilmente', 'Usando preguntas calibradas para asegurarte de que sus "síes" son genuinos y no por complacer', 'Ignorando la relación y centrándote solo en los números'), 'Usando preguntas calibradas para asegurarte de que sus "síes" son genuinos y no por complacer', 11 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'Encontrar el Cisne Negro', 'Los "cisnes negros" son piezas de información desconocidas y sorprendentes que, si se descubren, pueden cambiar por completo el curso de la negociación. Son las incógnitas que no sabías que no sabías.', 'Descubrir que la empresa con la que negocias está a punto de ser comprada y necesita cerrar tu trato urgentemente para mejorar sus cifras es un "cisne negro" que te da una enorme ventaja.', '¿Qué es un "Cisne Negro" en una negociación?', jsonb_build_array('Una información clave y desconocida que cambia drásticamente la negociación', 'Un problema insuperable que arruina el trato', 'Una táctica de negociación muy común'), 'Una información clave y desconocida que cambia drásticamente la negociación', 12 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'La Empatía Táctica', 'No se trata de sentir el dolor del otro (simpatía), sino de entender su perspectiva y sus emociones para poder influir en ellas. Es reconocer su punto de vista sin necesidad de estar de acuerdo.', '"Puedo ver por qué te sientes así, y entiendo las razones que te llevan a esa conclusión". Esta frase muestra comprensión sin ceder en tu propia posición.', '¿Cuál es la diferencia entre empatía táctica y simpatía?', jsonb_build_array('La simpatía es estar de acuerdo con el otro; la empatía táctica es entender su perspectiva para influir en ella', 'La empatía táctica solo se usa con terroristas', 'No hay ninguna diferencia'), 'La simpatía es estar de acuerdo con el otro; la empatía táctica es entender su perspectiva para influir en ella', 13 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'El Poder de un Resumen', 'Resumir la conversación y la posición de la otra persona es una herramienta poderosa. Combina el etiquetado de las emociones y la paráfrasis de los hechos, y su objetivo final es lograr un "Así es".', '"Entonces, si he entendido bien, el problema principal es que el plazo de entrega es muy ajustado, te preocupa que el equipo no dé abasto y sientes que la dirección no está valorando este riesgo. ¿Es correcto?".', '¿Cuál es el objetivo de hacer un buen resumen en una negociación?', jsonb_build_array('Hacer que la otra persona se sienta completamente escuchada y comprendida', 'Demostrar que eres más inteligente', 'Ganar tiempo para pensar en tu siguiente movimiento'), 'Hacer que la otra persona se sienta completamente escuchada y comprendida', 14 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'Usar Números Impares y Específicos', 'Los números específicos (como $10,870 en lugar de $11,000) suenan como si estuvieran basados en un cálculo cuidadoso y profundo. Dan la impresión de ser firmes y menos negociables.', 'Al hacer una oferta, en lugar de decir "Te ofrezco $50,000", decir: "Después de revisar los números, mi mejor oferta es $48,750".', '¿Por qué es efectivo usar números específicos en una oferta?', jsonb_build_array('Porque confunden a la otra parte', 'Porque son más fáciles de recordar', 'Porque parecen calculados y deliberados, lo que les da más credibilidad'), 'Porque parecen calculados y deliberados, lo que les da más credibilidad', 15 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'El Principio de la Aversión a la Pérdida', 'La gente se siente más motivada a actuar para evitar una pérdida que para obtener una ganancia equivalente. Enmarcar tus propuestas en términos de lo que la otra persona podría perder si no llega a un acuerdo es una táctica poderosa.', 'En lugar de "Si aceptas, ganarás un 10% de eficiencia", decir "Si no hacemos este cambio, seguirás perdiendo cientos de horas de trabajo cada mes".', 'La aversión a la pérdida significa que...', jsonb_build_array('La gente siempre evita negociar', 'La gente teme más perder algo que tiene que la alegría de ganar algo equivalente', 'A la gente le encanta ganar'), 'La gente teme más perder algo que tiene que la alegría de ganar algo equivalente', 16 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'La Trampa del "Sí" y el Compromiso', 'Los vendedores tradicionales buscan obtener pequeños "síes" para arrinconar al cliente. Voss advierte que esto genera desconfianza. La gente se pone en guardia ante las "trampas de sí". Un "no" es más seguro para el interlocutor.', 'Vendedor tradicional: "¿Quieres mejorar tu negocio? (Sí). ¿Quieres ganar más dinero? (Sí). ¿Entonces por qué no compras mi producto?". El cliente se siente manipulado.', '¿Por qué puede ser contraproducente buscar un "sí" a toda costa?', jsonb_build_array('Porque el "sí" siempre es una mentira', 'Porque la gente se siente manipulada y se pone a la defensiva', 'Porque el "no" es más fácil de obtener'), 'Porque la gente se siente manipulada y se pone a la defensiva', 17 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'La Importancia del Tono de Voz (Voz de Locutor de Medianoche)', 'Voss identifica tres tonos de voz clave: 1) La voz de locutor de medianoche (calmada, grave, tranquilizadora), 2) La voz positiva y juguetona (amigable, sonriente), y 3) La voz directa y asertiva (usar con moderación). La voz de locutor de medianoche es la más efectiva para bajar la tensión.', 'Cuando un cliente está alterado, en lugar de igualar su energía, el negociador baja el ritmo y adopta un tono grave y calmado: "Entiendo. Háblame de ello".', '¿Qué tono de voz recomienda Voss para calmar una situación tensa?', jsonb_build_array('La voz positiva y juguetona', 'La voz de locutor de medianoche', 'La voz directa y asertiva'), 'La voz de locutor de medianoche', 18 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', '"¿Cómo se supone que voy a hacer eso?"', 'Esta es una pregunta calibrada de oro cuando la otra parte te hace una demanda irrazonable. Se dice con deferencia y respeto, no con agresividad. Obliga a la otra parte a ponerse en tu lugar y a considerar tus problemas.', 'Cliente: "Necesito que me bajes el precio un 50%". Vendedor (con tono calmado y respetuoso): "¿Cómo se supone que voy a hacer eso?".', '¿Qué efecto tiene la pregunta "¿Cómo se supone que voy a hacer eso?"?', jsonb_build_array('Muestra debilidad y te hace perder la negociación', 'Invita a la otra parte a ayudarte a resolver tu problema y a reconsiderar su demanda', 'Es una forma agresiva de decir "no"'), 'Invita a la otra parte a ayudarte a resolver tu problema y a reconsiderar su demanda', 19 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'No Dividas la Diferencia', 'Dividir la diferencia (por ejemplo, tú pides 10, yo ofrezco 6, y quedamos en 8) a menudo lleva a un mal resultado para ambas partes. Es una solución perezosa. Es mejor usar las técnicas de negociación para que la otra parte ceda en tus términos.', 'En lugar de aceptar dividir la diferencia, un buen negociador usaría preguntas calibradas: "¿Cómo podemos trabajar juntos para que ese precio sea viable para mí?".', '¿Por qué Chris Voss se opone a "dividir la diferencia"?', jsonb_build_array('Porque es matemáticamente incorrecto', 'Porque es una salida fácil que a menudo conduce a resultados mediocres', 'Porque siempre favorece a la otra parte'), 'Porque es una salida fácil que a menudo conduce a resultados mediocres', 20 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'La Regla del 7-38-55', 'La comunicación se compone de un 7% de contenido (las palabras), un 38% de tono de voz y un 55% de lenguaje corporal. Por eso es vital prestar atención a cómo dices las cosas y a las señales no verbales del otro, no solo a lo que dicen.', 'Alguien dice "Sí, estoy de acuerdo" (7%) pero su tono es dubitativo (38%) y su cuerpo está tenso y con los brazos cruzados (55%). La verdad está en el 93% no verbal.', 'Según la regla 7-38-55, ¿qué es lo más importante en la comunicación cara a cara?', jsonb_build_array('Las palabras que se usan', 'El volumen al que se habla', 'El lenguaje corporal y el tono de voz'), 'El lenguaje corporal y el tono de voz', 21 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'Usar Pronombres Personales con Cuidado', 'Usar "yo" o "a mí" puede sonar egoísta. Usar "ellos" puede sonar como si te escondieras detrás de otros. Usar "nosotros" o "juntos" fomenta la colaboración, pero solo cuando se ha establecido una base de confianza.', 'Al principio de una negociación, en lugar de "Quiero que bajes el precio", es mejor preguntar "¿Cómo podemos llegar a un acuerdo?". El "podemos" es colaborativo.', '¿Qué pronombre es más efectivo para fomentar la colaboración una vez que hay confianza?', jsonb_build_array('Nosotros/Nuestro', 'Yo', 'Ellos'), 'Nosotros/Nuestro', 22 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'El Poder de un Buen "No"', 'Un "No" no es un fracaso, sino una herramienta para aclarar posiciones. Un "No" puede significar muchas cosas: "No estoy listo aún", "No lo entiendo", "No me lo puedo permitir", "Necesito más información". Tu trabajo es descubrir qué significa.', 'Cliente: "No, no puedo firmar este contrato". Negociador: "Entiendo. ¿Qué parte del contrato te preocupa más?".', '¿Cuál es la forma correcta de reaccionar ante un "No"?', jsonb_build_array('Terminar la negociación inmediatamente', 'Entenderlo como una invitación a explorar y preguntar más', 'Presionar más fuerte para conseguir un "sí"'), 'Entenderlo como una invitación a explorar y preguntar más', 23 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'La Prueba de Vida', 'En negociación de rehenes, "prueba de vida" es la evidencia de que el rehén sigue vivo. En los negocios, significa asegurarse de que las personas con las que negocias para implementar un acuerdo (el equipo de tu contraparte) están a bordo y son capaces de ejecutarlo.', '"Me parece fantástico que tú y yo estemos de acuerdo, pero ¿cómo nos aseguramos de que tu equipo de implementación tiene los recursos y la motivación para llevar esto a cabo?".', '¿Qué significa la "prueba de vida" en un contexto empresarial?', jsonb_build_array('Verificar que el CEO de la otra empresa sigue en su puesto', 'Asegurar la capacidad y el compromiso del equipo que ejecutará el acuerdo', 'Pedir ver una demostración del producto en vivo'), 'Asegurar la capacidad y el compromiso del equipo que ejecutará el acuerdo', 24 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'La Paradoja de la Negociación Justa', 'La palabra "justo" es un arma de doble filo. La gente puede usarla para manipularte ("Solo quiero lo que es justo..."). La mejor defensa es anticiparlo y decir primero: "Quiero que sientas que te están tratando de forma justa en todo momento. Si en algún punto no es así, por favor, dímelo".', 'Al inicio de una reunión: "Antes de empezar, quiero dejar claro que mi objetivo es llegar a un acuerdo que sea beneficioso para ambos y, sobre todo, que sientas que ha sido un proceso justo".', '¿Cómo se puede neutralizar el uso manipulador de la palabra "justo"?', jsonb_build_array('Evitando la palabra "justo" a toda costa', 'Introduciendo el concepto de justicia tú primero de forma positiva', 'Acusando a la otra persona de ser injusta'), 'Introduciendo el concepto de justicia tú primero de forma positiva', 25 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'El Valor del Silencio Pausado', 'Usar una pausa deliberada después de que tu contraparte hable o después de que tú uses un espejo o una etiqueta es muy efectivo. El silencio crea un vacío que la otra persona se sentirá impulsada a llenar, a menudo revelando información extra.', 'Cliente: "Necesito un descuento". Negociador (usando un espejo): "¿Un descuento?". Y luego, silencio total, esperando a que el cliente elabore.', '¿Cuál es el propósito de una pausa silenciosa en la negociación?', jsonb_build_array('Incitar a la otra persona a seguir hablando y revelar más información', 'Planear tu siguiente argumento en secreto', 'Mostrar que no estás interesado'), 'Incitar a la otra persona a seguir hablando y revelar más información', 26 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'Negociar en el Terreno del Otro', 'La negociación no trata sobre ti ni sobre tus argumentos. Trata sobre la otra persona y lo que hay en su mente. Toda la preparación y las técnicas deben centrarse en entender y navegar la perspectiva, las emociones y la realidad de tu contraparte.', 'Un vendedor deja de hablar de las características de su producto y empieza a hacer preguntas sobre los desafíos diarios de su cliente, centrando toda la conversación en el mundo del cliente.', '¿Cuál es el enfoque central de la filosofía de negociación de Chris Voss?', jsonb_build_array('Centrarse en tus propias necesidades y argumentos', 'Centrarse completamente en la perspectiva y las emociones de la otra persona', 'Buscar un punto medio lógico entre ambas partes'), 'Centrarse completamente en la perspectiva y las emociones de la otra persona', 27 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'Generar un Email que Funcione', 'Para reactivar una conversación por email, Voss propone un método radical: un email corto y provocador de una sola frase. "¿Has renunciado a este proyecto?". Es una pregunta de "no" que juega con la aversión a la pérdida y provoca una respuesta rápida.', 'Tras una semana de silencio del cliente, en lugar de un largo email de seguimiento, enviar únicamente: "Asumo que ya no es una prioridad. ¿Has descartado el proyecto?".', '¿Qué tipo de email propone Voss para reactivar a una contraparte silenciosa?', jsonb_build_array('Un email largo con muchos detalles y recordatorios', 'Un email muy corto, con una pregunta orientada al "no" para provocar una respuesta', 'Un email con una oferta de descuento inmediato'), 'Un email muy corto, con una pregunta orientada al "no" para provocar una respuesta', 28 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'El Poder de la Reputación', 'Tu reputación de ser duro pero justo te precede. En una negociación, la forma en que te comportas no solo afecta el trato actual, sino también todos los tratos futuros y cómo te perciben en tu industria. Juega limpio, pero sé firme.', 'Un negociador es conocido por cumplir siempre su palabra, pero también por no ceder ante tácticas de presión. La gente que negocia con él sabe que debe ir preparada y ser honesta.', '¿Por qué es crucial gestionar tu reputación como negociador?', jsonb_build_array('Porque afecta cómo te tratarán en negociaciones futuras', 'Porque te permitirá ganar siempre sin ceder nada', 'Porque una mala reputación asusta a la gente'), 'Porque afecta cómo te tratarán en negociaciones futuras', 29 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'Reconocer y Usar las Palabras Clave', 'Presta atención a las palabras que tu contraparte usa con frecuencia o con énfasis. Esas palabras son importantes para ellos. Reflejarlas (espejo) o usarlas en tus resúmenes muestra que estás prestando atención y te ayuda a conectar.', 'Si un cliente repite varias veces la palabra "legado", significa que es un concepto clave para él. El negociador debería usar esa palabra: "¿Cómo ayuda este acuerdo a construir el legado que buscas?".', '¿Qué debes hacer cuando identificas una "palabra clave" usada por tu contraparte?', jsonb_build_array('Evitar usar esa palabra para no parecer que le copias', 'Incorporarla en tus propias frases para mostrar que entiendes su importancia', 'Corregirle si usa la palabra de forma incorrecta'), 'Incorporarla en tus propias frases para mostrar que entiendes su importancia', 30 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'La Desventaja de ser el Primero en Anclar el Precio', 'Contrario a la creencia popular de que siempre hay que ser el primero en dar una cifra, Voss advierte que esto puede ser una desventaja si no tienes suficiente información. Corres el riesgo de anclar muy bajo o de forma poco realista. Es mejor que el otro ancle primero si es posible.', 'Un consultor, en lugar de dar su tarifa, pregunta al cliente: "¿Cuál es el presupuesto que tienen asignado para este tipo de proyecto?". Así obtiene un ancla de la otra parte.', '¿Cuándo es peligroso ser el primero en dar un precio?', jsonb_build_array('Solo cuando negocias con amigos', 'Cuando no tienes suficiente información sobre el presupuesto o el valor para la otra parte', 'Nunca, siempre es mejor anclar primero'), 'Cuando no tienes suficiente información sobre el presupuesto o el valor para la otra parte', 31 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'Revelar tus Motivaciones', 'Cuando te ganas la confianza, ser transparente sobre tus motivaciones puede ser muy útil. Decirle a tu contraparte *por qué* necesitas algo puede humanizarte y hacer que estén más dispuestos a ayudarte a encontrar una solución.', '"La razón por la que necesito cerrar este acuerdo antes del viernes es porque mi jefe tiene que presentarlo en la junta directiva, y un resultado positivo aquí nos daría a ambos mucha visibilidad positiva".', '¿En qué momento es apropiado revelar tus motivaciones?', jsonb_build_array('Una vez que has establecido un grado de confianza y rapport', 'Al principio de todo, para mostrar tus cartas', 'Nunca, siempre debes ocultar tus verdaderas razones'), 'Una vez que has establecido un grado de confianza y rapport', 32 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'Usar el Miedo a los Plazos', 'Los plazos hacen que la gente actúe. A menudo, la acción real en una negociación ocurre justo antes de que se cumpla un plazo. Puedes usar esto a tu favor, pero ten cuidado de no revelar tus propios plazos si no es estratégico.', 'Un negociador sabe que la otra parte tiene un plazo interno para tomar una decisión. En lugar de ceder antes, espera hasta el último momento, sabiendo que la presión sobre ellos aumentará.', '¿Cuándo ocurre la mayor parte de la acción en una negociación con plazos?', jsonb_build_array('Justo antes de que el plazo expire', 'Al principio de la negociación', 'Exactamente a la mitad del tiempo disponible'), 'Justo antes de que el plazo expire', 33 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'El Efecto de la Similaridad', 'La gente confía más y es más amable con aquellos con quienes comparte algo en común (la similaridad). Buscar puntos en común, ya sea un hobby, un conocido o una experiencia compartida, es una forma efectiva de construir rapport.', 'Un negociador se da cuenta de que su contraparte tiene una foto de un velero en su oficina y comenta que él también es aficionado a la vela. Esta conexión personal suaviza la interacción.', '¿Cuál es el propósito de encontrar puntos en común con tu contraparte?', jsonb_build_array('Construir rapport y confianza a través del principio de similaridad', 'Demostrar que tienes más experiencia de vida que ellos', 'Desviar la conversación de los temas importantes'), 'Construir rapport y confianza a través del principio de similaridad', 34 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'Preparar un Pliego de Negociación', 'Voss recomienda preparar un documento simple antes de cualquier negociación, que incluya: 1) Tu objetivo, 2) Un resumen de los hechos conocidos, 3) Las etiquetas y auditorías de acusaciones que prepararás, y 4) Las preguntas calibradas que planeas usar.', 'Antes de una llamada, un vendedor anota: Objetivo: Cerrar el trato por $15k. Hechos: Necesitan la solución en 2 meses. Etiquetas: "Parece que les preocupa el coste de implementación". Preguntas: "¿Cómo se vería un proyecto exitoso para ustedes?".', '¿Cuál es el objetivo principal de preparar un "pliego de negociación"?', jsonb_build_array('Organizar tus pensamientos y estrategias antes de la negociación', 'Tener un guion para leer durante la llamada', 'Enviar un documento formal a la otra parte'), 'Organizar tus pensamientos y estrategias antes de la negociación', 35 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'El Poder de un "No" Protegido', 'En lugar de forzar un "sí", puedes enmarcar una pregunta para que un "no" signifique acuerdo. Esto le da a la otra persona la sensación de protección y control.', 'En lugar de "¿Te gustaría tener una reunión la próxima semana?", preguntar: "¿Estarías en contra de que tengamos una breve llamada de 15 minutos la próxima semana?". Decir "no" es fácil y significa que aceptas la reunión.', '¿Cuál de estas preguntas está diseñada para obtener un "no" como respuesta positiva?', jsonb_build_array('"¿Quieres comprar esto?"', '"¿Sería ridículo que te propusiera esto?"', '"¿Estás de acuerdo con los términos?"'), '"¿Sería ridículo que te propusiera esto?"', 36 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'La Amenaza del "Otro"', 'En una negociación, a menudo hay personas influyentes que no están en la sala. Es crucial identificar a estas partes interesadas y entender su impacto. Puedes usar preguntas como: "¿Cómo afecta esto al resto de tu equipo?".', 'Un vendedor está a punto de cerrar un trato con un gerente, pero pregunta: "¿Qué pasará si tu director financiero no aprueba la partida presupuestaria? ¿Cómo podemos presentarle esto de la mejor manera?".', '¿Por qué es importante considerar a las personas que no están en la negociación?', jsonb_build_array('Porque pueden tener el poder de bloquear o aprobar el acuerdo', 'Para invitarlas a la siguiente reunión', 'Porque no tienen ninguna importancia'), 'Porque pueden tener el poder de bloquear o aprobar el acuerdo', 37 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'El Engaño de la Sonrisa', 'Una sonrisa genuina (una sonrisa de Duchenne) involucra los músculos alrededor de los ojos. Una sonrisa falsa no. Prestar atención a estos detalles no verbales puede ayudarte a detectar si la amabilidad de tu contraparte es genuina o una táctica.', 'Un cliente sonríe mientras dice que está de acuerdo, pero sus ojos permanecen fríos y sin arrugas en las comisuras. Es una señal para proceder con cautela.', '¿Cómo se puede diferenciar una sonrisa genuina de una falsa?', jsonb_build_array('Una sonrisa genuina involucra los músculos alrededor de los ojos', 'Las sonrisas genuinas siempre muestran los dientes', 'Por el sonido de la risa que la acompaña'), 'Una sonrisa genuina involucra los músculos alrededor de los ojos', 38 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'El Valor de la Escucha Activa', 'La base de todas las técnicas de Voss es la escucha activa. No es solo esperar tu turno para hablar, sino enfocarte completamente en el otro, con el objetivo de entender su mundo. Todas las herramientas (espejos, etiquetas, resúmenes) son manifestaciones de la escucha.', 'Un negociador apaga su teléfono, cierra su correo y se concentra al 100% en las palabras, el tono y el lenguaje corporal de su interlocutor, sin pensar en su propia respuesta hasta que el otro haya terminado.', '¿Cuál es el fundamento de todas las técnicas de negociación de Chris Voss?', jsonb_build_array('El uso de la fuerza y la intimidación', 'Hablar de forma persuasiva', 'La escucha activa y profunda'), 'La escucha activa y profunda', 39 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'rompe-la-barrera-del-no', 'Rompe la Barrera del NO', 'Garantizar la Ejecución', 'Un acuerdo no significa nada si no se implementa. En la fase final, usa preguntas calibradas sobre la ejecución. Preguntas como "¿Cómo sabremos que estamos en el buen camino?" o "¿Qué pasa si algo sale mal?" ayudan a solidificar el acuerdo y a descubrir posibles problemas.', 'Una vez acordado el precio, el negociador pregunta: "Perfecto. ¿Cómo gestionaremos la comunicación entre nuestros equipos para asegurar una implementación sin problemas?".', '¿Qué tipo de preguntas ayudan a "garantizar la ejecución"?', jsonb_build_array('Preguntas "Cómo" y "Qué" centradas en la implementación y posibles problemas futuros', 'Preguntas sobre el pasado de la empresa', 'Preguntas que reabren la negociación del precio'), 'Preguntas "Cómo" y "Qué" centradas en la implementación y posibles problemas futuros', 40 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'La etapa más importante', 'La etapa de Investigación es la que más influye en el éxito de una venta mayor. > Los vendedores exitosos pasan más tiempo investigando que los menos exitosos. > Las habilidades de venta tradicionales (cierre, manejo de objeciones) pierden efectividad a medida que la venta crece.', 'Un vendedor de equipos industriales dedica los primeros 40 minutos de una reunión a preguntar sobre procesos, dificultades y consecuencias, antes de mencionar su producto. Su cliente, al final, siente que el vendedor comprende su negocio.', '¿Qué etapa de la llamada de ventas tiene mayor influencia en el éxito en ventas mayores?', jsonb_build_array('La investigación (descubrimiento de necesidades)', 'La obtención de compromiso (cierre)', 'Los preliminares (apertura)', 'La demostración de capacidad'), 'La investigación (descubrimiento de necesidades)', 1 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'Necesidades implícitas vs explícitas', 'En ventas pequeñas, las necesidades implícitas (problemas, dificultades) predicen el éxito. > En ventas mayores, lo que predice el éxito son las necesidades explícitas (deseos o intenciones de acción concretas). > El vendedor debe convertir las implícitas en explícitas.', 'Un cliente dice: "Nuestra máquina actual es difícil de operar" (implícita). El vendedor pregunta: "¿Cuánto le cuesta en horas extras?" y el cliente responde: "Necesitamos un sistema más fácil de usar" (explícita). La venta avanza.', '¿Cuál de estas frases del cliente es una necesidad explícita en una venta mayor?', jsonb_build_array('"Nuestro sistema actual es lento"', '"No estoy satisfecho con la calidad"', '"Tenemos problemas con el proveedor actual"', '"Necesitamos reducir el tiempo de ciclo en un 20%"'), '"Necesitamos reducir el tiempo de ciclo en un 20%"', 2 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'Las cuatro etapas de la llamada', 'Toda llamada de ventas, grande o pequeña, pasa por cuatro etapas: > 1. Preliminares (apertura) > 2. Investigar (preguntas) > 3. Demostrar capacidad (mostrar soluciones) > 4. Obtener compromiso (acuerdo para avanzar) > El equilibrio entre ellas varía según el tipo de venta.', 'En una venta de consultoría, la etapa de investigación puede durar horas; en una venta de mostrador, los preliminares duran solo segundos.', 'Ordene las cuatro etapas de una llamada de ventas según su secuencia típica:', jsonb_build_array('Obtener compromiso → Demostrar capacidad → Investigar → Preliminares', 'Preliminares → Investigar → Demostrar capacidad → Obtener compromiso', 'Investigar → Preliminares → Demostrar capacidad → Obtener compromiso', 'Preliminares → Demostrar capacidad → Obtener compromiso → Investigar'), 'Preliminares → Investigar → Demostrar capacidad → Obtener compromiso', 3 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'El error de las preguntas abiertas y cerradas', 'La distinción entre preguntas abiertas y cerradas no predice el éxito en ventas mayores. > Algunos de los mejores vendedores usan casi solo preguntas cerradas. > Lo que importa es el contenido psicológico (situación, problema, implicación, necesidad-pago), no si son abiertas o cerradas.', 'Un vendedor exitoso pregunta: "¿Tiene problemas de confiabilidad?" (cerrada). El cliente responde "Sí". Luego pregunta: "¿Qué impacto tiene eso en sus entregas?" (cerrada otra vez). Logra la venta.', 'Según la investigación de Huthwaite, ¿cuál es la relación entre preguntas abiertas/cerradas y el éxito en ventas mayores?', jsonb_build_array('Las preguntas abiertas son siempre más efectivas', 'No hay relación medible entre ambos tipos y el éxito', 'Solo las preguntas abiertas predicen el éxito', 'Las preguntas cerradas son siempre más efectivas'), 'No hay relación medible entre ambos tipos y el éxito', 4 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'El modelo SPIN', 'SPIN es el acrónimo de cuatro tipos de preguntas que usan los vendedores exitosos: > Situación, Problema, Implicación, Necesidad-pago. > No es una fórmula rígida, sino una guía para desarrollar necesidades explícitas.', 'Vendedor: "¿Qué equipo usa?" (Situación) → "¿Le da problemas?" (Problema) → "¿Cómo afecta eso a sus costos?" (Implicación) → "¿Le ayudaría reducir esos costos?" (Necesidad-pago).', '¿Qué significa cada letra del modelo SPIN?', jsonb_build_array('Solución, Precio, Interés, Negociación', 'Seguimiento, Propuesta, Indagación, Negocio', 'Situación, Problema, Implicación, Necesidad-pago', 'Sondeo, Perspectiva, Inversión, Necesidad'), 'Situación, Problema, Implicación, Necesidad-pago', 5 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'Cierre: menos es más', 'Las técnicas de cierre tradicionales (presuntivo, alternativo, etc.) pierden efectividad a medida que aumenta el tamaño de la venta. > En ventas mayores, el uso excesivo de cierres reduce la tasa de éxito. > Los vendedores exitosos obtienen compromiso sin técnicas agresivas.', 'Un vendedor intenta un cierre presuntivo: "¿Entonces empiezo la entrega el martes?" El cliente se incomoda y dice: "Todavía no he decidido". La reunión termina mal.', 'En un estudio con productos de alto valor (precio promedio $109), ¿qué efecto tuvo la capacitación en técnicas de cierre?', jsonb_build_array('No hubo cambios significativos', 'Aumentó la tasa de éxito del 42% al 58%', 'La tasa de éxito se duplicó', 'Redujo la tasa de éxito del 42% al 33%'), 'Redujo la tasa de éxito del 42% al 33%', 6 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'Compromiso real: avances vs continuaciones', 'En ventas mayores, un avance es una acción concreta que mueve la venta hacia adelante (ej: reunión con decisor, prueba de producto). > Una continuación son palabras bonitas sin acción ("me llamas luego"). > Los vendedores exitosos apuntan a avances, no a continuaciones.', 'Cliente dice: "Excelente presentación, me impresionó". Eso es una continuación. Cliente dice: "El martes presentará su propuesta al comité de compras". Eso es un avance.', '¿Cuál es un ejemplo de avance en una venta mayor?', jsonb_build_array('"Nos gustó mucho su producto"', '"Acordemos que el jueves prueben su máquina en nuestra planta"', '"Gracias por venir, lo pensaré"', '"Estamos impresionados, llámeme en un mes"'), '"Acordemos que el jueves prueben su máquina en nuestra planta"', 7 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'Construir valor antes de la solución', 'Ofrecer soluciones (ventajas o beneficios) demasiado pronto en la llamada genera objeciones. > Primero hay que desarrollar la gravedad del problema mediante preguntas de implicación. > El cliente debe percibir que el problema es grande antes de que una solución costosa tenga sentido.', 'Vendedor: "Nuestro sistema reduce errores". Cliente: "No vale la pena, solo tengo pocos errores". Vendedor entrenado: "¿Cuánto le cuesta cada error en horas extras y clientes insatisfechos?" Cliente: "Nunca lo vi así, necesito una solución".', '¿Qué tipo de pregunta ayuda a que el cliente perciba un problema como más grave y urgente?', jsonb_build_array('Preguntas de situación', 'Preguntas cerradas', 'Preguntas de precio', 'Preguntas de implicación'), 'Preguntas de implicación', 8 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'Beneficios verdaderos vs ventajas', 'En ventas mayores, un beneficio verdadero muestra cómo su producto satisface una necesidad explícita expresada por el cliente. > Una ventaja solo muestra cómo el producto puede usarse o ayudar, sin necesidad explícita. > Los beneficios son mucho más poderosos que las ventajas.', 'Cliente dice explícitamente: "Necesito reducir tiempos de cambio". Vendedor responde: "Nuestra máquina reduce el cambio en un 40%". Eso es un beneficio. Si solo dice: "Nuestra máquina tiene cambio rápido", es una ventaja.', '¿Cuál de las siguientes es una declaración de Beneficio según la definición de SPIN Selling?', jsonb_build_array('"El precio base es \$78.000" (Característica)', '"Este sistema tiene 8 niveles de codificación" (Característica)', '"Como usted necesita tasa de error menor a 1/100.000, la nuestra de 1/1.500.000 la satisface" (Beneficio)', '"Nuestra baja tasa de error puede usarse para verificar datos" (Ventaja)'), '"Como usted necesita tasa de error menor a 1/100.000, la nuestra de 1/1.500.000 la satisface" (Beneficio)', 9 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'El peligro de las ventajas', 'Las ventajas (mostrar cómo el producto puede ayudar sin necesidad explícita) generan objeciones. > Cada ventaja tiende a ser seguida de una objeción del cliente. > El manejo de objeciones trata el síntoma; prevenir objeciones evitando ventajas prematuras trata la causa.', 'Vendedor da una ventaja: "Nuestro procesador de textos elimina la necesidad de reescribir". Cliente objeta: "No pagaré \$15.000 solo para reducir algunas reescrituras".', 'Según la investigación de Linda Marsh, ¿qué respuesta del cliente es más probable después de que el vendedor da una ventaja?', jsonb_build_array('Objeción', 'Silencio', 'Aprobación entusiasta', 'Pregunta sobre precio'), 'Objeción', 10 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'Prevención de objeciones', 'La mejor manera de manejar objeciones es prevenirlas. > Las objeciones surgen cuando se ofrece una solución sin haber construido suficiente valor. > Usar preguntas SPIN (especialmente implicación y necesidad-pago) reduce las objeciones en más de un 50%.', 'Un grupo de vendedores recibió entrenamiento en SPIN sin mencionar la palabra "objeción". Después, las objeciones por hora de venta se redujeron un 55%.', '¿Qué estrategia reduce más efectivamente las objeciones en ventas mayores?', jsonb_build_array('Aprender 10 técnicas para responder objeciones de precio', 'Cerrar más fuerte al inicio de la llamada', 'Hablar primero de las características del producto', 'Desarrollar necesidades explícitas con preguntas SPIN antes de ofrecer soluciones'), 'Desarrollar necesidades explícitas con preguntas SPIN antes de ofrecer soluciones', 11 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'Apertura sin fórmulas mágicas', 'No existe una "mejor manera" de abrir una llamada de ventas. > Las declaraciones de beneficio inicial y hablar de intereses personales funcionan en ventas pequeñas, pero no en grandes. > Lo importante es obtener permiso para hacer preguntas y evitar hablar de soluciones demasiado pronto.', 'Un vendedor abre con: "Sr. Cliente, sé que está ocupado. ¿Podría hacerle algunas preguntas para entender su situación actual antes de mostrarle algo?" El cliente asiente. La llamada fluye.', 'En ventas mayores, ¿cuál de estas aperturas es más efectiva según la investigación?', jsonb_build_array('"Solo quiero contarle las características de nuestro nuevo sistema"', '"Nuestro producto le ahorrará miles de dólares"', '"¿Podría hacerle algunas preguntas sobre su operación actual?"', '"¿Le gusta el golf? Veo el trofeo en su oficina"'), '"¿Podría hacerle algunas preguntas sobre su operación actual?"', 12 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'Preguntas de situación: úselas con moderación', 'Las preguntas de situación recopilan hechos y antecedentes. > Son necesarias, pero los vendedores inexpertos abusan de ellas y aburren al cliente. > Los vendedores exitosos las reducen al mínimo, preparando información antes de la llamada.', 'Vendedor novato pregunta: "¿Cuántos empleados tiene? ¿Hace cuánto está en el cargo? ¿Cuál es su volumen de ventas?" El cliente se impacienta.', '¿Cuál es la relación entre el número de preguntas de situación y el éxito en ventas mayores?', jsonb_build_array('No hay ninguna relación', 'A más preguntas de situación, más éxito', 'Las llamadas exitosas tienen menos preguntas de situación', 'Solo las preguntas de situación predicen el éxito'), 'Las llamadas exitosas tienen menos preguntas de situación', 13 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'Preguntas de problema: el primer paso', 'Las preguntas de problema exploran dificultades, insatisfacciones y errores. > Descubren necesidades implícitas. > En ventas pequeñas son muy poderosas; en ventas mayores son necesarias pero no suficientes.', '"¿Está satisfecho con la confiabilidad de su equipo actual?" "¿Qué desventajas tiene su proceso actual?" "¿Le resulta difícil manejar picos de demanda?"', '¿Qué tipo de pregunta es la más indicada para descubrir necesidades implícitas?', jsonb_build_array('Preguntas de situación', 'Preguntas de implicación', 'Preguntas de problema', 'Preguntas de necesidad-pago'), 'Preguntas de problema', 14 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'Preguntas de implicación: hacer crecer el problema', 'Las preguntas de implicación toman un problema y exploran sus efectos y consecuencias. > Hacen que el cliente sienta el problema como más grave, urgente y costoso. > Son "tristes" porque se centran en lo negativo, pero son clave para justificar soluciones caras.', '"¿Qué efecto tiene esa baja productividad en sus plazos de entrega?" "¿Cómo impacta esa rotación de personal en sus costos de capacitación?" "Si no resuelve esto, ¿cómo afectará su competitividad?"', 'Según la "Regla de Quincy", ¿cómo se diferencian las preguntas de implicación de las de necesidad-pago?', jsonb_build_array('Las de implicación son tristes (centradas en problema), las de necesidad-pago son felices (centradas en solución)', 'Las de implicación son felices, las de necesidad-pago son tristes', 'Las de implicación son abiertas, las de necesidad-pago cerradas', 'Son iguales, solo cambia el orden'), 'Las de implicación son tristes (centradas en problema), las de necesidad-pago son felices (centradas en solución)', 15 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'Preguntas de necesidad-pago: centrarse en la solución', 'Las preguntas de necesidad-pago preguntan sobre el valor o utilidad de resolver un problema. > Son "felices" y hacen que el cliente verbalice los beneficios de la solución. > El cliente termina diciendo: "Sí, eso me ayudaría porque..."', '"¿Le ayudaría reducir los errores en un 20%?" "¿Qué beneficios traería tener un sistema más rápido?" "¿De qué otra manera podría aprovechar esa mejora en calidad?"', '¿Qué logra principalmente una pregunta de necesidad-pago?', jsonb_build_array('Descubrir problemas ocultos', 'Cerrar la venta inmediatamente', 'Hacer que el cliente explique los beneficios de la solución', 'Hacer que el cliente se sienta triste por su situación'), 'Hacer que el cliente explique los beneficios de la solución', 16 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'Nuevos productos: no venda campanas y silbatos', 'En el lanzamiento de nuevos productos, los vendedores tienden a dar tres veces más características y ventajas que con productos existentes. > Esto reduce el éxito. > La mejor estrategia es lanzar el producto en términos de problemas que resuelve y enseñar preguntas SPIN para descubrir esos problemas.', 'Un grupo experimental que aprendió a vender un nuevo equipo médico enfocándose en problemas (no en características) superó al resto en 54% en ventas el primer año.', 'Cuando se lanza un producto nuevo, ¿qué error cometen con más frecuencia los vendedores?', jsonb_build_array('Hacer demasiadas preguntas de situación', 'Pasar poco tiempo con el cliente', 'No usar técnicas de cierre', 'Dar demasiadas características y ventajas (campanas y silbatos)'), 'Dar demasiadas características y ventajas (campanas y silbatos)', 17 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'El cierre no funciona en clientes sofisticados', 'Los compradores profesionales (agentes de compras, altos ejecutivos) reaccionan negativamente a las técnicas de cierre. > Un estudio mostró que 34 de 54 compradores dijeron que las técnicas de cierre les hacen menos propensos a comprar. > Usar cierres con ellos daña la relación.', 'Un comprador de British Petroleum tenía un cajón con tarjetas de técnicas de cierre. Cuando un vendedor usaba una, sacaba la tarjeta y decía: "Esa es su primera oportunidad. Si usa otra, no hay venta".', '¿Cómo reaccionan típicamente los compradores profesionales ante las técnicas de cierre estándar?', jsonb_build_array('Se sienten más dispuestos a comprar', 'Piden más información sobre el producto', 'Se sienten menos dispuestos a comprar', 'Les da igual'), 'Se sienten menos dispuestos a comprar', 18 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'Satisfacción postventa y cierre', 'Los clientes que son presionados para cerrar están menos satisfechos con su compra después. > Un estudio en retail mostró que clientes atendidos por vendedores entrenados en cierre tenían menor satisfacción y menor intención de recompra. > En ventas mayores (relación continua), esto es aún más crítico.', 'Compra una máquina porque el vendedor insistió: "Si no decide hoy, sube el precio". Una semana después, siente que fue presionado y se arrepiente. No volverá a comprarle.', 'En una venta que implica una relación postventa continua, ¿qué efecto tienen las técnicas de cierre agresivas?', jsonb_build_array('Aumentan la lealtad del cliente', 'Reducen la satisfacción y la recompra', 'No afectan la satisfacción', 'Mejoran la percepción de profesionalismo'), 'Reducen la satisfacción y la recompra', 19 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'El refuerzo del cierre: por qué creemos que funciona', 'Los vendedores creen en el cierre porque a veces, justo después de un cierre, obtienen un pedido. > El refuerzo es inmediato, pero la causa real no es el cierre, sino el desarrollo de necesidades previo. > Es un error de atribución: confundir correlación con causalidad.', 'Un vendedor usa un cierre alternativo: "¿Empiezo en septiembre o noviembre?" El cliente elige septiembre. El vendedor cree que el cierre fue la causa, pero en realidad el cliente ya había decidido comprar por las preguntas SPIN previas.', '¿Por qué los vendedores suelen sobreestimar la efectividad de las técnicas de cierre?', jsonb_build_array('Porque los gerentes de ventas lo exigen', 'Porque funciona en todas las culturas', 'Porque el cierre es seguido inmediatamente por un pedido (refuerzo), aunque no sea la causa', 'Porque los clientes se lo dicen directamente'), 'Porque el cierre es seguido inmediatamente por un pedido (refuerzo), aunque no sea la causa', 20 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'Objeciones de precio: síntoma, no causa', 'Las objeciones de precio aumentan cuando el vendedor da muchas características. > Las características hacen al cliente más sensible al precio. > Si su producto es caro, dar muchas características le juega en contra; si es barato, puede ayudar.', 'Un vendedor cambió de un producto barato (muchas características) a uno caro (mismo estilo). Sus objeciones de precio se dispararon. Se le reentrenó en preguntas SPIN y las objeciones cayeron.', 'Si su producto es más caro que el de la competencia, ¿qué comportamiento debe evitar?', jsonb_build_array('Obtener avances', 'Hacer preguntas de implicación', 'Dar muchas características del producto', 'Resumir beneficios'), 'Dar muchas características del producto', 21 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'El vendedor como director de obra', 'En ventas mayores, usted no está presente en la mayoría de las "llamadas de venta" internas. > Sus patrocinadores (clientes convencidos) venden por usted cuando usted no está. > Debe "ensayarlos" haciéndoles describir los beneficios (no los detalles del producto) mediante preguntas de necesidad-pago.', 'En lugar de decirle al comprador: "Dígale al vicepresidente que tenemos auditoría automática", el vendedor pregunta: "¿Qué beneficio obtendría el vicepresidente al reducir inventario?" El comprador internaliza el valor y lo vende mejor.', '¿Cuál es la mejor manera de preparar a un cliente para que "venda" su producto internamente?', jsonb_build_array('Enviarle correos semanales con novedades', 'Mostrarle un video de la fábrica', 'Hacer que le explique a usted los beneficios mediante preguntas de necesidad-pago', 'Darle un manual de características técnicas'), 'Hacer que le explique a usted los beneficios mediante preguntas de necesidad-pago', 22 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'Planificación de preguntas de implicación', 'Las preguntas de implicación son difíciles de hacer en vivo sin preparación. > Los vendedores exitosos las planifican antes de la llamada. > Técnica: escriba un problema potencial y luego pregúntese: "¿Qué dificultades relacionadas trae?" Convierta cada dificultad en una pregunta.', 'Problema: "La máquina es difícil de usar". Dificultades: escasez de operarios calificados, horas extras, rotación. Preguntas: "¿Cómo afecta la escasez a su producción?" "¿Qué costo tienen las horas extras?"', '¿Cuál es la razón principal por la que muchos vendedores no hacen suficientes preguntas de implicación?', jsonb_build_array('Porque los clientes se enojan', 'Porque no son efectivas', 'Porque no tienen tiempo en la llamada', 'Porque no las planifican con anticipación'), 'Porque no las planifican con anticipación', 23 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'Beneficios en el ciclo de venta largo', 'Las ventajas (tipo A) son más efectivas al principio del ciclo de venta, pero pierden fuerza a medida que se avanza. > Los beneficios (tipo B) son efectivos en todo el ciclo. > Los vendedores experimentados cambian de ventajas a beneficios a medida que madura la venta.', 'En la primera llamada, dar una ventaja ("nuestro sistema es fácil de usar") puede generar interés. En la quinta llamada, si no hay una necesidad explícita, dar la misma ventaja genera objeciones.', '¿Qué tipo de declaración mantiene su efectividad a lo largo de todo el ciclo de venta?', jsonb_build_array('Ventajas (Tipo A)', 'Beneficios (Tipo B)', 'Características', 'Declaraciones de precio'), 'Beneficios (Tipo B)', 24 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'Evite el "efecto receta médica"', 'En ventas mayores, el cliente es experto en su propio negocio. > Decirle lo que es bueno para él ("usted necesita esto porque...") genera resistencia. > En cambio, haga que el cliente descubra el valor por sí mismo mediante preguntas.', 'Vendedor novato: "Nuestro sistema aumentará su productividad". Cliente: "¿Cómo sabe lo que necesito?" Vendedor entrenado: "¿Cómo cree que una mayor productividad impactaría sus costos?" Cliente: "Bueno, reduciría nuestras horas extras, eso sí sería valioso".', '¿Cómo se denomina la técnica de hacer que el cliente verbalice sus propios beneficios?', jsonb_build_array('Declaración de beneficio inicial', 'Venta consultiva tradicional', 'Cierre presuntivo', 'Preguntas de necesidad-pago'), 'Preguntas de necesidad-pago', 25 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'El poder de la variedad en aperturas', 'Los vendedores menos efectivos abren todas sus llamadas de la misma manera. > Los más efectivos varían su estilo (a veces con declaración de beneficio, otras con una pregunta directa, etc.). > Usar la misma apertura repetida con el mismo cliente resulta mecánico e irritante.', 'Un vendedor usa la misma frase: "Sé que está ocupado, pero si le dedica 15 minutos, podría ahorrarle miles de dólares". La primera vez causa buena impresión; la segunda, con el mismo cliente, suena a disco rayado.', '¿Qué caracteriza la apertura de llamada de los vendedores más efectivos?', jsonb_build_array('Siempre usan una declaración de beneficio inicial', 'Varían el estilo según la situación y el cliente', 'Siempre preguntan por el presupuesto primero', 'Siempre hablan de intereses personales'), 'Varían el estilo según la situación y el cliente', 26 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'El verdadero propósito de los preliminares', 'El objetivo de la etapa preliminar no es vender, ni impresionar. > Es obtener el consentimiento del cliente para pasar a la etapa de investigación. > Es decir: que el cliente acepte que usted le haga preguntas.', '"Señor Cliente, antes de contarle sobre nuestros servicios, ¿me permite hacerle algunas preguntas para entender su situación?" El cliente asiente. Ya tiene permiso para investigar.', '¿Cuál es la función principal de los preliminares en una venta mayor?', jsonb_build_array('Cerrar el pedido temprano', 'Obtener permiso para hacer preguntas y pasar a la investigación', 'Construir una amistad personal', 'Mostrar todas las características del producto'), 'Obtener permiso para hacer preguntas y pasar a la investigación', 27 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'Las 4 reglas de oro del aprendizaje de habilidades', '1. Practique un comportamiento a la vez. > 2. Pruebe el nuevo comportamiento al menos tres veces antes de juzgarlo. > 3. Enfoque en cantidad antes que calidad (hágalo mucho, aunque salga mal). > 4. Practique en situaciones seguras, no en su cuenta más importante.', 'Un vendedor decide practicar solo preguntas de problema durante dos semanas, sin preocuparse si las hace bien o mal. Las hace en cuentas pequeñas. Al final, mejora naturalmente.', '¿Cuál es la regla más importante para aprender una nueva habilidad de venta?', jsonb_build_array('Aprender 5 habilidades nuevas al mismo tiempo para ahorrar tiempo', 'Esperar a que sea perfecta antes de usarla', 'Practicarla en la cuenta más grande para forzar el aprendizaje', 'Practicar un comportamiento a la vez, en situaciones seguras y con enfoque en cantidad'), 'Practicar un comportamiento a la vez, en situaciones seguras y con enfoque en cantidad', 28 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'Cantidad antes que calidad', 'En el aprendizaje de habilidades (idiomas, golf, ventas), enfocarse en cantidad (hacer mucho, aunque mal) acelera el aprendizaje más que enfocarse en calidad (hacer poco, pero perfecto). > Los vendedores que hacen muchas preguntas SPIN, aunque al principio sean torpes, mejoran más rápido que los que esperan a hacerlas perfectas.', 'Un programa de entrenamiento carísimo (USD 650.000) basado en calidad fracasó. Otro económico basado en cantidad (hacer muchas preguntas) logró que los vendedores pasaran de 0 a 12 preguntas problema por llamada.', 'Cuando aprende una nueva técnica de preguntas SPIN, ¿cuál es el mejor enfoque?', jsonb_build_array('Perfeccionar la redacción antes de usarla con clientes', 'Usarla muchas veces, aunque sea torpe, enfocándose en cantidad', 'Usarla solo una vez por llamada para no arriesgar', 'Esperar a que el gerente la apruebe'), 'Usarla muchas veces, aunque sea torpe, enfocándose en cantidad', 29 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'Riesgo de la presión en decisiones grandes', 'La presión funciona en decisiones pequeñas (comprar un caramelo), pero es contraproducente en decisiones grandes. > Cuanto mayor es la decisión, más negativamente reacciona la persona a la presión. > Las técnicas de cierre son una forma de presión.', 'Presionar a un cliente para que compre un automóvil de \$30.000 genera incomodidad y rechazo. Presionar para que compre un chicle de \$1 puede funcionar.', '¿Cómo se comporta el efecto de la presión al aumentar el tamaño de la decisión?', jsonb_build_array('No tiene relación con el tamaño de la decisión', 'Aumenta su efectividad', 'Se mantiene constante', 'Disminuye su efectividad, volviéndose contraproducente'), 'Disminuye su efectividad, volviéndose contraproducente', 30 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'El vendedor sí importa (en grandes ventas)', 'En ventas pequeñas, separas al vendedor del producto. Puedes odiar al vendedor y comprar el producto. > En ventas grandes, vendedor y producto son difíciles de separar. > El cliente compra una relación, no solo una máquina.', 'El autor compró un proyector de un vendedor desagradable (venta pequeña). Pero para un sistema contable de \$70.000, aunque el producto era bueno, no compró porque no quería una relación larga con el vendedor.', '¿Por qué el vendedor cobra más importancia relativa en las ventas grandes?', jsonb_build_array('Porque el cliente es menos inteligente', 'Porque el gerente de ventas lo exige', 'Porque el producto es más caro', 'Porque la venta implica una relación continua; no se puede separar el producto del vendedor'), 'Porque la venta implica una relación continua; no se puede separar el producto del vendedor', 31 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'El miedo al error público', 'En ventas grandes, el cliente no solo teme perder dinero; teme que otros sepan que se equivocó. > Las decisiones grandes son más públicas. > Eso hace al cliente más cauto y más necesitado de valor.', 'Un comprador gasta \$40.000 en investigación (solo él lo sabe) con facilidad. Pero para gastar \$1.500 adicionales en un área donde sus colegas están involucrados, necesita mucho más convencimiento.', 'Además del precio, ¿qué factor aumenta la precaución del cliente en ventas mayores?', jsonb_build_array('La edad del vendedor', 'La distancia geográfica', 'El color del producto', 'El miedo a cometer un error público visible para otros'), 'El miedo a cometer un error público visible para otros', 32 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'El resumen de beneficios antes del compromiso', 'Antes de pedir un compromiso (avance), los vendedores exitosos resumen los puntos clave de la discusión, especialmente los beneficios. > En ventas grandes (llamadas largas), el cliente puede haber olvidado la mitad de lo hablado. > El resumen enfoca la mente del cliente en el valor.', '"Hemos visto cómo nuestro sistema reduciría sus costos de energía en un 15%, eliminaría el cuello de botella en el área de empaque y mejoraría su cumplimiento normativo. ¿Le parece que tiene sentido entonces que acordemos una prueba piloto la próxima semana?"', '¿Por qué es importante resumir los beneficios antes de proponer un compromiso?', jsonb_build_array('Para que el cliente no tenga tiempo de pensar', 'Porque en llamadas largas el cliente olvida puntos clave; el resumen los recupera y justifica el avance', 'Para impresionar con memoria', 'Para alargar la llamada y parecer más profesional'), 'Porque en llamadas largas el cliente olvida puntos clave; el resumen los recupera y justifica el avance', 33 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'Verificación de preocupaciones clave', 'Antes de proponer un compromiso, el vendedor exitoso pregunta si hay alguna preocupación o duda no resuelta. > Esto evita que el cliente saque una objeción en el momento del cierre, lo que sería más antagónico. > Es mejor sacar a la luz las dudas por iniciativa propia.', '"Antes de seguir adelante, Sra. Cliente, ¿hay algún aspecto que no haya cubierto o alguna preocupación que debamos resolver?" Ella dice: "Sí, no me ha quedado claro el tema del soporte técnico". Usted responde: "Muy bien, abordemos eso ahora".', '¿Cuál es el beneficio de verificar preocupaciones clave antes de proponer un compromiso?', jsonb_build_array('Hace que el cliente se sienta culpable', 'Acelera el cierre porque el cliente se siente presionado', 'Evita tener que hacer preguntas SPIN', 'Permite resolver objeciones en un ambiente no antagónico, en lugar de que surjan como protesta al cierre'), 'Permite resolver objeciones en un ambiente no antagónico, en lugar de que surjan como protesta al cierre', 34 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'Proponer, no preguntar', 'En la obtención de compromiso, los vendedores exitosos proponen un siguiente paso lógico, en lugar de "preguntar si puede cerrar". > La frase "¿Podría darme el pedido?" es débil. > La frase "Entonces, el siguiente paso lógico sería que su ingeniero jefe nos visite la próxima semana para ver la máquina en funcionamiento" es más efectiva.', '"No preguntó ''¿me permite una demostración?''. Dijo: ''El siguiente paso sería que usted y su equipo vengan a nuestra planta el martes a las 10. ¿Les parece bien?''"', '¿Qué forma de obtener compromiso es más efectiva en ventas mayores?', jsonb_build_array('"Si no decide ahora, perderá la oportunidad"', '"¿Prefiere la entrega en marzo o abril?"', '"El siguiente paso lógico sería que probemos el producto en su línea. ¿Qué día le funciona?"', '"¿Podría darme el pedido hoy?"'), '"El siguiente paso lógico sería que probemos el producto en su línea. ¿Qué día le funciona?"', 35 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'El ABC de las ventas grandes no es "siempre cerrar"', 'El viejo eslogan "Siempre Estar Cerrando" (Always Be Closing) es perjudicial en ventas grandes. > El ABC de las ventas grandes debería ser "Siempre Estar Investigando" o "Siempre Estar Aportando Valor". > El cierre es una consecuencia natural de una buena investigación, no un fin en sí mismo.', 'Un vendedor que presiona para cerrar en cada interacción es visto como manipulador. Uno que investiga, descubre problemas, desarrolla implicaciones y luego propone un avance es visto como consultor.', '¿Qué debería significar el "ABC" en ventas mayores?', jsonb_build_array('Always Be Closing (Siempre Estar Cerrando)', 'Always Be Investigating (Siempre Estar Investigando) o Always Be Creating Value', 'Always Be Cutting prices (Siempre Estar Bajando Precios)', 'Always Be Calling (Siempre Estar Llamando)'), 'Always Be Investigating (Siempre Estar Investigando) o Always Be Creating Value', 36 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'La Regla de los 4 segundos... no aplica', 'A diferencia de las enseñanzas de algunos gurús agresivos, en ventas mayores la primera impresión no define el éxito. > La investigación muestra que las primeras impresiones importan mucho menos que el desarrollo de necesidades. > No se preocupe por esos primeros segundos; preocúpese por las preguntas que hará después.', 'Un vendedor nervioso al inicio, que tartamudea, pero que luego hace excelentes preguntas de implicación, gana la venta. Otro con una apertura perfecta pero sin habilidades SPIN, la pierde.', 'En ventas mayores, ¿qué tan cruciales son los primeros 4 segundos de la llamada?', jsonb_build_array('Definen si el cliente le comprará o no', 'Son el factor más determinante del éxito', 'Su influencia es muy limitada; lo importante es la etapa de investigación', 'Solo importan si el cliente es muy observador'), 'Su influencia es muy limitada; lo importante es la etapa de investigación', 37 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'La venta como apertura de relación', 'El objetivo del cierre no debería ser cerrar una transacción, sino abrir una relación. > Hans Stennek, consultor sueco: "Nunca he sido partidario del cierre porque mi objetivo no es cerrar la venta sino abrir una relación". > Esto es especialmente cierto en ventas mayores, donde hay múltiples compras futuras.', 'Un vendedor obtiene un pedido pequeño, pero trata mal al cliente. No habrá recompra. Otro obtiene un avance (reunión con el director) y cultiva la relación. A largo plazo, gana diez veces más.', '¿Cuál es el verdadero objetivo de la obtención de compromiso en una venta mayor?', jsonb_build_array('Hacer que el cliente firme cualquier cosa', 'Cerrar el pedido cueste lo que cueste', 'Usar la técnica de cierre más agresiva', 'Obtener un avance que abra una relación de largo plazo'), 'Obtener un avance que abra una relación de largo plazo', 38 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'Las características no venden en grandes ventas', 'Las características son neutrales o ligeramente negativas en ventas mayores. > Los clientes sofisticados no se impresionan con listas de características; quieren saber cómo resolverán sus problemas. > Demasiadas características aumentan las objeciones de precio.', 'Un vendedor enumera: 8 niveles de codificación, memoria de 512K, estabilizador de voltaje. El cliente pregunta: "¿Cuánto cuesta?" y "¿eso resuelve mi problema de integración con SAP?" El vendedor no sabe responder a lo segundo.', '¿Qué efecto tienen las características en el cliente durante una venta mayor?', jsonb_build_array('Ayudan a cerrar más rápido', 'Son neutrales o ligeramente negativas; aumentan la sensibilidad al precio', 'Siempre generan una orden de compra', 'Son muy convincentes'), 'Son neutrales o ligeramente negativas; aumentan la sensibilidad al precio', 39 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'ventas-spin', 'Ventas SPIN', 'La práctica deliberada de SPIN', 'Leer sobre SPIN no mejora sus habilidades; debe practicar deliberadamente. > Elija un comportamiento (ej: preguntas de problema). > Practique solo ese durante dos semanas en cuentas seguras. > Mida cuántas hace por llamada (cantidad). > Luego pase al siguiente comportamiento.', 'Semana 1-2: solo preguntas de situación, meta: 10 por llamada. Semana 3-4: solo preguntas de problema, meta: 15 por llamada. Semana 5-6: solo preguntas de implicación, meta: 5 por llamada (son difíciles). Semana 7-8: solo preguntas de necesidad-pago, meta: 8 por llamada. Al final, integra todo. Las ventas aumentan 27% según estudio Motorola.', '¿Cuál es el primer paso para implementar el modelo SPIN en su trabajo diario?', jsonb_build_array('Asistir a un seminario de una semana', 'Leer el libro tres veces', 'Enseñar SPIN a su gerente', 'Elegir un comportamiento (ej: preguntas de problema) y practicarlo enfocado en cantidad en cuentas seguras durante dos semanas'), 'Elegir un comportamiento (ej: preguntas de problema) y practicarlo enfocado en cantidad en cuentas seguras durante dos semanas', 40 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Nunca le hagas sombra al amo', 'Siempre debes hacer que quienes están por encima de ti se sientan superiores. Si eclipsas a tu superior, despiertas su inseguridad y te conviertes en una amenaza, aunque seas leal. El poder real no tolera competidores visibles.', 'Nicolas Fouquet, ministro de Luis XIV, organizó una fiesta tan lujosa que eclipsó al rey. Poco después fue arrestado y pasó el resto de su vida en prisión. Su error no fue fallar, sino brillar más que su superior.', '¿Por qué Fouquet perdió su poder?', jsonb_build_array('Porque cometió fraude', 'Porque gastó demasiado dinero', 'Porque hizo sentir inferior a su superior'), 'Porque hizo sentir inferior a su superior', 1 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'No confíes demasiado en los amigos, aprende a usar a los enemigos', 'Los amigos se vuelven confiados y descuidados; los enemigos, en cambio, buscan demostrar su valor. Un antiguo enemigo convertido en aliado trabajará con más disciplina y cautela que un amigo de confianza.', 'El emperador Taizong de China incorporó antiguos enemigos a su gobierno. Estos trabajaban con extrema disciplina para demostrar lealtad, mientras sus amigos se volvían perezosos y arrogantes.', '¿Por qué un enemigo puede ser más útil que un amigo?', jsonb_build_array('Porque busca demostrar su valor', 'Porque actúa con miedo', 'Porque no tiene alternativas'), 'Porque busca demostrar su valor', 2 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Oculta tus intenciones', 'Mantén a los demás en la oscuridad sobre tus verdaderos planes. Si revelas tus intenciones, das ventaja a tus rivales, que podrán prepararse para contrarrestarte. El misterio es una fuente de poder.', 'Otto von Bismarck ocultaba sus verdaderos planes políticos. Sus rivales creían entenderlo y se relajaban, mientras él avanzaba paso a paso. Cuando reaccionaron, ya no podían detenerlo.', '¿Qué ocurre al mostrar tus intenciones?', jsonb_build_array('Generas confianza', 'Das ventaja al rival', 'Aceleras acuerdos'), 'Das ventaja al rival', 3 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Di siempre menos de lo necesario', 'Cuanto más hablas, más común y predecible pareces. El silencio y la brevedad generan respeto, porque los demás proyectan poder en tus palabras no dichas. Hablar poco hace que cada palabra tenga peso.', 'Luis XIV hablaba poco y con frases medidas. Su silencio hacía que cada palabra pareciera importante. La corte proyectaba en él poder donde no decía nada.', '¿Qué comunica más poder?', jsonb_build_array('Hablar mucho', 'Hablar poco y preciso', 'Explicar todo'), 'Hablar poco y preciso', 4 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Defiende tu reputación con la vida', 'La reputación es la base del poder. Una vez dañada, te vuelves vulnerable a ataques y traiciones. Debes atacar cualquier rumor o desprestigio de inmediato, sin piedad. Tu nombre es tu escudo.', 'César Borgia atacaba de inmediato cualquier rumor que dañara su imagen. Sabía que una reputación debilitada invitaba a enemigos a aprovecharse.', '¿Por qué la reputación es poder?', jsonb_build_array('Porque genera miedo', 'Porque define cómo te tratan', 'Porque evita errores'), 'Porque define cómo te tratan', 5 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Llama la atención a cualquier precio', 'La invisibilidad es el peor escenario para quien busca poder. Es preferible ser criticado o polémico a ser ignorado. La atención, incluso negativa, te coloca en el mapa y te da relevancia.', 'P. T. Barnum entendió que la controversia atraía más público que el anonimato. Prefería críticas y escándalos antes que ser ignorado.', '¿Qué es más peligroso?', jsonb_build_array('Mala fama', 'Exceso de exposición', 'Invisibilidad'), 'Invisibilidad', 6 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Deja que otros trabajen por ti, pero llévate el crédito', 'El tiempo ahorrado es poder acumulado. Utiliza el talento y esfuerzo de otros para lograr tus objetivos, pero asegúrate de que el reconocimiento público recaiga sobre ti. El crédito construye tu figura.', 'Thomas Edison se apoyó en el trabajo de asistentes y técnicos, pero el reconocimiento público quedó en su nombre. Así consolidó su figura histórica.', '¿Qué se gana al tomar el crédito?', jsonb_build_array('Poder simbólico', 'Tiempo', 'Popularidad'), 'Poder simbólico', 7 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Haz que los demás vengan a ti', 'Quien persigue, pierde control. Si fuerzas a otros a moverse, ellos revelan sus debilidades y estrategias. Espera en tu posición y haz que los adversarios vengan a ti. Así conservas la iniciativa.', 'Napoleón evitaba atacar primero. Forzaba a sus enemigos a moverse, revelando errores estratégicos. Esperar le daba ventaja.', '¿Qué ventaja tiene no perseguir?', jsonb_build_array('Más rapidez', 'Más control', 'Menos esfuerzo'), 'Más control', 8 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Vence con acciones, no con argumentos', 'Discutir genera resistencia y desgaste. Los hechos, en cambio, silencian cualquier debate. Demuestra tu poder con resultados visibles, no con palabras. La acción es la única refutación que nadie puede ignorar.', 'Galileo demostraba sus teorías con experimentos visibles en lugar de discutir con filósofos. La evidencia hablaba por él.', '¿Por qué discutir debilita?', jsonb_build_array('Consume tiempo', 'Genera resistencia', 'Expone errores'), 'Genera resistencia', 9 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Evita a los infelices y desafortunados', 'La desgracia y la negatividad se contagian. Asociarte con personas fracasadas o amargadas arrastrará tu suerte y reputación. Rodéate de personas exitosas y con energía positiva.', 'En la corte, quienes se asociaban con personas caídas en desgracia terminaban perdiendo poder junto a ellas. La energía ajena influye en tu destino.', '¿Qué contagia la negatividad?', jsonb_build_array('Fracaso', 'Lentitud', 'Dudas'), 'Fracaso', 10 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Haz que los demás dependan de ti', 'La independencia de otros debilita tu poder. Vuelvete indispensable controlando información, habilidades únicas o recursos clave. Quien no puede prescindir de ti está bajo tu influencia.', 'En las cortes europeas, los consejeros que controlaban información clave se volvían indispensables. El gobernante no podía prescindir de ellos sin perder estabilidad.', '¿Qué genera mayor poder a largo plazo?', jsonb_build_array('Ser simpático', 'Ser indispensable', 'Ser obediente'), 'Ser indispensable', 11 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Usa la honestidad selectiva', 'Una verdad estratégica, admitida a tiempo, desarma más que una mentira. Confesar errores menores te hace parecer sincero y bajas las defensas del otro, permitiéndote ocultar tus objetivos mayores.', 'Líderes y diplomáticos admitían errores menores para parecer sinceros. Esa confesión generaba confianza y permitía ocultar intenciones más profundas.', '¿Por qué funciona la honestidad selectiva?', jsonb_build_array('Porque genera culpa', 'Porque genera confianza', 'Porque elimina riesgos'), 'Porque genera confianza', 12 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Apela al interés propio, no a la gratitud', 'La gratitud es inestable y se olvida rápido. El interés propio, en cambio, es un motor constante. Si quieres lealtad duradera, muestra a los demás cómo se benefician al apoyarte, no apeles a favores pasados.', 'Muchos gobernantes perdieron aliados al apelar a favores pasados. Quienes mostraban beneficios claros mantenían apoyos firmes.', '¿Qué motiva más una acción?', jsonb_build_array('La lealtad', 'El beneficio propio', 'La costumbre'), 'El beneficio propio', 13 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Hazte pasar por amigo, actúa como espía', 'La información es la moneda del poder. Escucha más de lo que hablas. En toda conversación, busca descubrir secretos, intenciones y debilidades ajenas sin levantar sospechas. La amistad fingida es la mejor cobertura.', 'En la corte, quienes escuchaban más de lo que hablaban reunían secretos y debilidades ajenas. Saber más otorgaba ventaja silenciosa.', '¿Qué otorga mayor control?', jsonb_build_array('Simpatía', 'Información', 'Presencia'), 'Información', 14 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Aplasta totalmente a tu enemigo', 'No dejes heridas abiertas. Si vences a un enemigo, destrúyelo por completo. Los problemas a medias siempre regresan con más fuerza. La clemencia mal aplicada se transforma en amenaza futura.', 'Los enemigos perdonados en el pasado regresaban con más venganza cuando tenían oportunidad. El conflicto incompleto es peligroso.', '¿Qué riesgo existe al no cerrar un conflicto?', jsonb_build_array('Venganza', 'Costos', 'Confusión'), 'Venganza', 15 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Usa la ausencia para aumentar respeto', 'La escasez crea valor. Si estás siempre disponible, te vuelves común y prescindible. Retirarte estratégicamente hace que los demás te valoren más y te respeten. La ausencia genera deseo.', 'Figuras de poder que se retiraban estratégicamente eran más deseadas y respetadas. La disponibilidad constante reducía su impacto.', '¿Qué genera la ausencia?', jsonb_build_array('Deseo', 'Rechazo', 'Olvido'), 'Deseo', 16 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Mantén a los demás en suspenso', 'La imprevisibilidad genera control. Si los demás no pueden anticipar tus movimientos, actúan con cautela. La rutina y la predecibilidad te vuelven vulnerable. Cambia tus patrones sin aviso.', 'Líderes impredecibles descolocaban a rivales y aliados. Al no poder anticiparlos, los demás actuaban con cautela constante.', '¿Por qué la imprevisibilidad es poderosa?', jsonb_build_array('Genera miedo', 'Obliga a adaptarse', 'Confunde planes'), 'Obliga a adaptarse', 17 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'No te aísles', 'El aislamiento te vuelve vulnerable. Sin aliados, sin información y sin protección, cualquier ataque te encuentra solo. Construye redes, mantén contactos y cultiva alianzas. El poder necesita de otros.', 'Quienes se retiraban del juego político perdían información, apoyo y protección. El aislamiento facilitaba ataques inesperados.', '¿Qué riesgo tiene aislarse?', jsonb_build_array('Perder tiempo', 'Perder información', 'Perder enfoque'), 'Perder información', 18 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Conoce con quién estás tratando', 'No todos reaccionan igual. El error fatal es tratar a todos con la misma fórmula. Observa el carácter de cada persona: orgullosos, inseguros, ambiciosos, miedosos. Adapta tu trato a su psicología.', 'Errores fatales ocurrían cuando se trataba a todos por igual. Comprender el carácter del otro evitaba ofensas y reacciones peligrosas.', '¿Por qué es clave adaptar el trato?', jsonb_build_array('Para agradar', 'Para evitar conflictos', 'Para ganar tiempo'), 'Para evitar conflictos', 19 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'No te comprometas con nadie', 'La libertad de acción es poder. Las alianzas cerradas te atan y limitan. Mantén opciones abiertas; así podrás cambiar de bando si el equilibrio lo exige. Los compromisos permanentes son cadenas.', 'Los estrategas más hábiles evitaban alianzas cerradas. Mantener opciones abiertas les permitía cambiar de bando si convenía.', '¿Qué ventaja tiene no comprometerse?', jsonb_build_array('Más apoyo', 'Más libertad', 'Más rapidez'), 'Más libertad', 20 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Hazte el tonto para atrapar a los tontos', 'Hacerte parecer menos inteligente de lo que eres desarma a los demás. Si te subestiman, bajan la guardia y cometen errores. La aparente ingenuidad es una trampa perfecta para que otros revelen sus verdaderas intenciones.', 'Personajes astutos fingían ingenuidad para que sus rivales bajaran la guardia. Al sentirse superiores, cometían errores y revelaban información clave.', '¿Por qué aparentar menos inteligencia da poder?', jsonb_build_array('Generas simpatía', 'Provoca descuidos ajenos', 'Reduce conflictos'), 'Provoca descuidos ajenos', 21 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Usa la táctica de la rendición', 'Ceder en apariencia puede ser una estrategia poderosa. Rendirte temporalmente desarma al adversario, que baja la guardia. Aprovecha ese respiro para reorganizarte y contraatacar cuando sea el momento. La rendición fingida es una trampa.', 'Algunos líderes se rendían temporalmente para ganar tiempo y reorganizar fuerzas. El adversario, confiado, bajaba la vigilancia.', '¿Cuándo rendirse es estratégico?', jsonb_build_array('Cuando no hay opciones', 'Cuando se gana tiempo', 'Cuando se evita conflicto'), 'Cuando se gana tiempo', 22 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Concentra tus fuerzas', 'El enfoque multiplica el poder. Dispersar tus recursos te debilita. Concéntrate en un solo punto, una sola batalla, un solo objetivo. La victoria decisiva en un frente te da ventaja en todos los demás.', 'Los estrategas más eficaces evitaban dispersarse. Al concentrar recursos en un solo punto, lograban victorias decisivas.', '¿Qué ocurre al dispersar fuerzas?', jsonb_build_array('Se gana flexibilidad', 'Se pierde impacto', 'Se reduce riesgo'), 'Se pierde impacto', 23 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Sé el perfecto cortesano', 'El poder también es saber comportarse en sociedad. Dominar las reglas sociales, saber cuándo hablar y cuándo callar, a quién halagar y a quién ignorar, es tan importante como cualquier estrategia. La inteligencia emocional protege.', 'En la corte, quienes dominaban las reglas sociales sobrevivían más que los brillantes pero imprudentes. Saber cuándo hablar y callar era clave.', '¿Qué define al cortesano eficaz?', jsonb_build_array('Ambición', 'Inteligencia emocional', 'Popularidad'), 'Inteligencia emocional', 24 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Recréate a ti mismo', 'No aceptes el rol que la sociedad o el pasado te imponen. Tienes el poder de reinventar tu imagen, tu personalidad y tus habilidades. Quien no cambia, se vuelve obsoleto. La reinvención es supervivencia.', 'Figuras históricas redefinieron su imagen pública para adaptarse a nuevas circunstancias. Quienes no cambiaron quedaron obsoletos.', '¿Por qué es clave redefinirse?', jsonb_build_array('Para agradar', 'Para sobrevivir', 'Para destacar'), 'Para sobrevivir', 25 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Mantén las manos limpias', 'El poder real no deja huellas. Si necesitas acciones impopulares o sucias, usa intermediarios. Así tu imagen queda limpia mientras otros cargan con la culpa. La apariencia de integridad es esencial.', 'Líderes usaban intermediarios para ejecutar acciones impopulares. Así evitaban manchar su imagen ante los demás.', '¿Por qué mantener las manos limpias?', jsonb_build_array('Evita castigos', 'Protege la reputación', 'Aumenta control'), 'Protege la reputación', 26 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Juega con la necesidad de creer', 'La gente necesita creer en algo más grande que ella misma. No ofrezcas hechos fríos; ofrece esperanza, propósito, una visión. Crea un sistema de creencias que una a las personas a tu alrededor. La fe genera lealtad irracional.', 'Líderes carismáticos creaban sistemas de creencias que unían a las personas. No ofrecían hechos, ofrecían esperanza.', '¿Qué mueve más a las personas?', jsonb_build_array('La lógica', 'La fe', 'La presión'), 'La fe', 27 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Actúa con audacia', 'La duda y la vacilación te debilitan. La audacia, incluso imprudente, intimida a los inseguros. Una acción firme y decidida impone respeto y descoloca a los rivales. El temor a equivocarte es más peligroso que el error mismo.', 'Decisiones firmes intimidaban a rivales inseguros. La audacia confundía y desarmaba oposiciones antes de formarse.', '¿Por qué la audacia intimida?', jsonb_build_array('Parece certeza', 'Reduce debate', 'Genera miedo'), 'Parece certeza', 28 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Planifica hasta el final', 'El que no anticipa las consecuencias, reacciona tarde. Planifica cada paso hasta el desenlace final, considerando los posibles giros. La improvisación es para los débiles. Anticipar evita trampas y sorpresas.', 'Muchos fracasos ocurrieron por no prever consecuencias. Los estrategas exitosos visualizaban el final antes de actuar.', '¿Qué riesgo tiene no planificar?', jsonb_build_array('Lentitud', 'Sorpresas', 'Falta de recursos'), 'Sorpresas', 29 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Haz que tus logros parezcan fáciles', 'El esfuerzo visible reduce la admiración. Si muestras el sudor y la lucha detrás de tus éxitos, pareces menos talentoso. Oculta el trabajo duro; que tus logros parezcan naturales, fruto de tu genio. El misterio aumenta el respeto.', 'Quienes ocultaban el trabajo detrás de sus éxitos parecían más talentosos y poderosos. Lo fácil impresiona más.', '¿Por qué ocultar el esfuerzo?', jsonb_build_array('Evita envidia', 'Aumenta admiración', 'Reduce críticas'), 'Aumenta admiración', 30 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Controla las opciones', 'Haz que otros crean que eligen libremente, pero dales solo opciones que te favorezcan. Ofrece dos alternativas, ambas beneficiosas para ti. Así el otro siente control, pero el resultado siempre es el que tú quieres.', 'Líderes astutos ofrecían solo dos opciones, ambas favorables para ellos. El otro sentía libertad, pero el resultado estaba controlado.', '¿Qué ventaja tiene controlar opciones?', jsonb_build_array('Evita conflictos', 'Dirige decisiones', 'Acelera acuerdos'), 'Dirige decisiones', 31 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Apela a las fantasías', 'La verdad es incómoda; la gente prefiere las fantasías. No les des realidades duras, dales ilusiones atractivas. Promételes transformación, éxito fácil, soluciones mágicas. Las fantasías movilizan más que los hechos.', 'Los grandes líderes ofrecían visiones atractivas en lugar de verdades incómodas. Prometían transformación, no sacrificio.', '¿Qué conecta más con las personas?', jsonb_build_array('Datos', 'Fantasías', 'Advertencias'), 'Fantasías', 32 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Descubre el talón de Aquiles de cada persona', 'Todos tienen una debilidad oculta: orgullo, miedo, ambición, inseguridad. Observa con atención y descubre esa falla. Una vez identificada, puedes usarla para influir, controlar o destruir. La debilidad ajena es tu herramienta.', 'Quienes observaban con atención detectaban inseguridades ocultas. Esa debilidad definía la estrategia de influencia.', '¿Por qué es clave detectar debilidades?', jsonb_build_array('Evita errores', 'Permite influir', 'Reduce conflictos'), 'Permite influir', 33 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Actúa como rey para que te traten como tal', 'La autoimagen que proyectas condiciona el trato que recibes. Si te comportas con dignidad, seguridad y límites claros, los demás te tratarán con respeto, incluso sin poder formal. No pidas respeto; exígelo con tu actitud.', 'Personas que se comportaban con dignidad y límites claros eran tratadas con respeto, incluso sin poder formal.', '¿Qué genera actuar con dignidad?', jsonb_build_array('Simpatía', 'Respeto', 'Popularidad'), 'Respeto', 34 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Domina el arte del tiempo', 'El momento lo es todo. Saber cuándo actuar y cuándo esperar es más importante que la acción misma. Actuar antes o después de tiempo arruina cualquier ventaja. El timing es la clave silenciosa del poder.', 'Los estrategas exitosos sabían cuándo avanzar y cuándo esperar. Actuar antes o después arruinaba ventajas.', '¿Por qué el tiempo es clave?', jsonb_build_array('Reduce riesgos', 'Define impacto', 'Ahorra recursos'), 'Define impacto', 35 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Desprecia lo que no puedas tener', 'La indiferencia es un arma poderosa. Si muestras deseo por lo que no puedes obtener, le das poder al otro. En cambio, despreciar lo inalcanzable quita valor a lo que el otro posee y te protege de la manipulación.', 'Ignorar provocaciones o pérdidas menores evitaba que el rival ganara poder emocional. No reaccionar es control.', '¿Qué logra la indiferencia?', jsonb_build_array('Evita conflicto', 'Quita poder al otro', 'Reduce estrés'), 'Quita poder al otro', 36 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Crea espectáculos memorables', 'La imagen domina la mente más que las palabras. Usa ceremonias, símbolos y puestas en escena para reforzar tu autoridad. Lo visual queda grabado en la memoria mucho más que los argumentos racionales. El espectáculo fija el poder.', 'Los gobernantes usaban ceremonias y símbolos para reforzar autoridad. Lo visual quedaba grabado en la memoria.', '¿Qué impacta más?', jsonb_build_array('Argumentos', 'Datos', 'Imagen'), 'Imagen', 37 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Piensa como quieras, pero compórtate como los demás', 'Diferenciarse demasiado en lo público genera rechazo y aislamiento. Puedes pensar de forma radical, pero no lo muestres. Adáptate a las normas sociales dominantes para sobrevivir y ganar influencia. La adaptación no es traición, es estrategia.', 'Quienes mostraban ideas radicales sin adaptación social eran aislados. Los inteligentes se mimetizaban sin perder visión.', '¿Por qué adaptarse al entorno?', jsonb_build_array('Para agradar', 'Para sobrevivir', 'Para destacar'), 'Para sobrevivir', 38 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Revuelve las aguas para atrapar peces', 'La emoción nubla el juicio. Si provocas enojo, confusión o miedo en tu rival, cometerá errores impulsivos. Mantén tu calma mientras el otro pierde el control. Quien se altera, pierde poder.', 'Provocar enojo o confusión llevaba al rival a cometer errores impulsivos. Mantener la calma era la verdadera ventaja.', '¿Qué ocurre cuando el otro se altera?', jsonb_build_array('Pierde enfoque', 'Comete errores', 'Se rinde'), 'Comete errores', 39 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Desprecia lo que es gratis', 'Lo que no cuesta dinero se subestima. Si das algo sin cobrar, parecerá que tiene poco valor. Cobrar por tu trabajo, incluso simbólicamente, crea percepción de valor. El precio es un mensaje.', 'Aquellos que cobraban por su valor eran más respetados. Lo gratuito era visto como débil o reemplazable.', '¿Qué comunica cobrar?', jsonb_build_array('Necesidad', 'Valor', 'Urgencia'), 'Valor', 40 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'No sigas los pasos de un grande', 'Imitar a una figura legendaria te condena a vivir en su sombra. Siempre serás comparado y considerado inferior. Forja tu propio camino, crea tu propio estilo. La originalidad construye poder.', 'Quienes imitaban a figuras legendarias vivían a su sombra. Los que innovaban construían identidad propia.', '¿Por qué no imitar?', jsonb_build_array('Genera rechazo', 'Limita identidad', 'Reduce creatividad'), 'Limita identidad', 41 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Golpea al pastor y las ovejas se dispersarán', 'El poder se concentra en el líder. Si neutralizas a la cabeza, el grupo pierde dirección y cohesión. Atacar al conjunto es desperdiciar energía. Enfócate en derribar a quien manda.', 'Al neutralizar al líder, el grupo perdía dirección y cohesión. Atacar al conjunto era menos eficaz.', '¿Dónde se concentra el poder?', jsonb_build_array('En el grupo', 'En el líder', 'En la estructura'), 'En el líder', 42 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Trabaja los corazones y las mentes', 'La imposición genera obediencia temporal; la conexión emocional genera lealtad real. Si quieres seguidores fieles, conecta con sus emociones, sus esperanzas y sus miedos. La razón convence, la emoción arrastra.', 'Los líderes que conectaban emocionalmente obtenían lealtad real. La imposición solo generaba obediencia temporal.', '¿Qué genera lealtad duradera?', jsonb_build_array('Miedo', 'Conexión emocional', 'Recompensas'), 'Conexión emocional', 43 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Usa el efecto espejo', 'Reflejar sutilmente el tono, ritmo, gestos y actitud del otro genera confianza y baja sus defensas. El espejo crea una sensación de comprensión y afinidad. Úsalo para establecer rapport y controlar la interacción.', 'Imitar tono, ritmo y actitud del otro generaba confianza y bajaba defensas. El espejo crea control sutil.', '¿Por qué el espejo funciona?', jsonb_build_array('Genera simpatía', 'Reduce tensión', 'Aumenta control'), 'Aumenta control', 44 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Predica el cambio, pero gradualmente', 'El cambio brusco asusta y genera resistencia. Introduce novedades de forma gradual, casi imperceptible. Así los demás se adaptan sin oponerse. Lo gradual se acepta; lo repentino se rechaza.', 'Los reformadores exitosos introducían cambios pequeños y progresivos. Los cambios radicales despertaban oposición inmediata.', '¿Por qué el cambio gradual funciona?', jsonb_build_array('Es más lento', 'Genera menos resistencia', 'Reduce costos'), 'Genera menos resistencia', 45 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Nunca parezcas demasiado perfecto', 'La perfección genera envidia. Los demás se sienten inferiores y eso despierta resentimiento oculto. Muestra fallas humanas menores, defectos controlados. Así desarmas la envidia y te vuelves más accesible.', 'Mostrar fallas humanas menores evitaba resentimiento. La perfección aislaba y provocaba ataques ocultos.', '¿Por qué mostrar imperfección?', jsonb_build_array('Genera empatía', 'Evita envidia', 'Reduce presión'), 'Evita envidia', 46 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'No vayas más allá de tu objetivo', 'El exceso destruye lo ganado. Muchos perdieron todo por querer más cuando ya habían obtenido suficiente. Saber detenerte, reconocer el momento de parar, es una forma de sabiduría. El límite protege el éxito.', 'Muchos perdieron poder por querer más cuando ya habían ganado. Saber detenerse preservaba la victoria.', '¿Qué riesgo tiene querer más?', jsonb_build_array('Fatiga', 'Exceso', 'Pérdida'), 'Pérdida', 47 ON CONFLICT (company_id, module, orden) DO NOTHING;
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (falabella_id, 'las-48-leyes-del-poder', '48 Leyes del Poder', 'Sé amorfo', 'La rigidez se rompe; la flexibilidad sobrevive. Quien se adapta a las circunstancias cambiantes nunca es vencido. No tengas una forma fija: cambia de estrategia, de imagen, de tácticas según el momento. Adaptarse es el poder final.', 'Quienes se adaptaban a nuevas circunstancias sobrevivían a crisis y cambios. Los rígidos quedaban expuestos.', '¿Por qué la adaptabilidad es clave?', jsonb_build_array('Reduce esfuerzo', 'Permite sobrevivir', 'Aumenta control'), 'Permite sobrevivir', 48 ON CONFLICT (company_id, module, orden) DO NOTHING;

  RAISE NOTICE 'Inserted % items for falabella', 168;
END
$$;
